window.LCE_GLOSSA_ANO_B_REVISADA = {
  "B|ADVENTO|1º Domingo|primeira-leitura|Is 63,16-17.19; 64,2-7": "(ROTEIRO EDITORIAL — ORAÇÃO DE ISAÍAS / POVO A DEUS; sem inserir versículos não selecionados)\n(CENA 1: POVO INVOCA DEUS)\nSENHOR / TU NOSSO PAI / DESDE SEMPRE NOSSO REDENTOR.\nPOR QUE NÓS AFASTAR DOS TEUS CAMINHOS / CORAÇÃO ENDURECER / NÃO TE RESPEITAR?\nPOR AMOR TEUS SERVOS / TRIBOS TUA HERANÇA / VOLTA PARA NÓS.\n(CENA 2: DESEJO DA MANIFESTAÇÃO DE DEUS)\nAH / SE TU RASGASSES CÉUS / DESCESSES!\nDIANTE DE TI / MONTANHAS TREMER.\nTU JÁ DESCER / MONTANHAS TREMER DIANTE DE TI.\nNENHUM OUVIDO OUVIU / NENHUM OLHO VIU OUTRO DEUS FAZER TANTO POR QUEM NELE ESPERA.\nTU IR ENCONTRO DE QUEM PRATICAR JUSTIÇA / LEMBRAR TEUS CAMINHOS.\n(CENA 3: CONFISSÃO DO POVO)\nTU INDIGNADO CONOSCO / PORQUE NÓS PECAMOS / MUITO TEMPO REBELDES.\nMAS NÓS ESPERAR SALVAÇÃO.\nNÓS TODOS COMO PESSOA IMPURA / NOSSAS AÇÕES JUSTAS COMO ROUPA SUJA.\nNÓS TODOS COMO FOLHAS SECAS CAIR / NOSSAS CULPAS COMO VENTO NOS LEVAR.\nNINGUÉM TEU NOME INVOCAR / NINGUÉM LEVANTAR PARA BUSCAR TEU APOIO.\nPARECER TUA FACE ESCONDIDA / NÓS SOFRER CONSEQUÊNCIAS NOSSAS FALTAS.\n(CENA 4: PAI E OLEIRO)\nMAS SENHOR / TU NOSSO PAI.\nNÓS BARRO / TU OLEIRO / TUAS MÃOS NOS FORMARAM.\nNÓS TODOS OBRA TUAS MÃOS.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|ADVENTO|1º Domingo|segunda-leitura|1Cor 1,3-9": "(ROTEIRO EDITORIAL — PAULO SE DIRIGE AOS CORÍNTIOS)\nPAULO → COMUNIDADE: GRAÇA E PAZ PARA VOCÊS / DE DEUS NOSSO PAI E SENHOR JESUS CRISTO.\nPOR VOCÊS / EU SEMPRE AGRADECER A DEUS / POR GRAÇA QUE ELE DEU EM CRISTO JESUS.\nEM CRISTO / VOCÊS RECEBER RIQUEZAS ESPIRITUAIS / PALAVRA / CONHECIMENTO.\nTESTEMUNHO SOBRE CRISTO / TORNAR-SE FIRME ENTRE VOCÊS.\nVOCÊS ESPERAR MANIFESTAÇÃO DE NOSSO SENHOR JESUS CRISTO / NENHUM DOM GRAÇA FALTAR.\nJESUS CRISTO FORTALECER VOCÊS ATÉ O FIM / PARA QUE NO DIA DELE / IRREPREENSÍVEIS.\nDEUS É FIEL / ELE CHAMAR VOCÊS PARA COMUNHÃO COM SEU FILHO JESUS CRISTO NOSSO SENHOR.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|ADVENTO|1º Domingo|evangelho|Mc 13,33-37": "(ROTEIRO EDITORIAL — JESUS FALA A DISCÍPULOS E A TODOS; casa e porteiro são exemplo)\nJESUS: CUIDADO / VIGIAR / VOCÊS NÃO SABER QUANDO MOMENTO CHEGAR.\n(CENA: DONO DA CASA VIAJA)\nHOMEM DONO CASA / VIAJAR.\nANTES SAIR / DAR PODER E RESPONSABILIDADE A SERVOS / CADA QUAL SUA TAREFA.\nAO PORTEIRO / ORDENAR: FICAR VIGIANDO.\n(CENA: RETORNO INCERTO)\nJESUS: VOCÊS VIGIAR / NÃO SABER QUANDO DONO CASA VOLTAR.\nPODE VOLTAR À TARDE / MEIA-NOITE / GALO CANTAR / AMANHECER.\nELE CHEGAR DE REPENTE / NÃO ENCONTRAR VOCÊS DORMINDO.\nJESUS: O QUE DIGO A VOCÊS / DIGO A TODOS / VIGIAR!\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|ADVENTO|2º Domingo|primeira-leitura|Is 40,1-5.9-11": "(ROTEIRO EDITORIAL — DIFERENCIAR A VOZ DE DEUS, VOZ QUE CLAMA E ARAUTO)\n(CENA 1: DEUS ENVIA CONSOLO)\nDEUS: CONSOLAR / CONSOLAR MEU POVO.\nJERUSALÉM / FALAR COM CARINHO / ANUNCIAR SOFRIMENTO E SERVIDÃO ACABARAM / CULPA PERDOADA / PUNIÇÃO PELOS PECADOS JÁ RECEBIDA.\n(CENA 2: VOZ NO DESERTO)\nVOZ CLAMAR: PREPARAR CAMINHO NO DESERTO PARA O SENHOR / ABRIR ESTRADA PARA DEUS.\nVALES ELEVAR / MONTANHAS E COLINAS ABAIXAR.\nESTRADAS TORTAS ENDIREITAR / CAMINHOS DIFÍCEIS APLANAR.\nGLÓRIA SENHOR MANIFESTAR / TODA HUMANIDADE VER / SENHOR MESMO FALOU.\n(CENA 3: ARAUTO ANUNCIA)\nMENSAGEIRO DE SIÃO / SUBIR MONTE ALTO / ANUNCIAR.\nMENSAGEIRO DE JERUSALÉM / FALAR FORTE / SEM MEDO.\nDIZER CIDADES DE JUDÁ: VEJAM / NOSSO DEUS!\nSENHOR DEUS VIR COM PODER / GOVERNO DELE FORTE / RECOMPENSA COM ELE.\n(CENA 4: IMAGEM DO PASTOR)\nSENHOR COMO PASTOR / CUIDAR SEU REBANHO.\nOVELHAS DISPERSAS / ELE REUNIR.\nCORDEIROS / SEGURAR NOS BRAÇOS.\nOVELHAS / CONDUZIR AO DESCANSO.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|ADVENTO|2º Domingo|segunda-leitura|2Pd 3,8-14": "(ROTEIRO EDITORIAL — PEDRO FALA À COMUNIDADE; linguagem apocalíptica não deve ser tratada como previsão datada)\nCARÍSSIMOS / UMA COISA NÃO ESQUECER.\nDIANTE SENHOR / UM DIA COMO MIL ANOS / MIL ANOS COMO UM DIA.\nALGUMAS PESSOAS PENSAR SENHOR ATRASAR PROMESSA / MAS NÃO.\nELE PACIENTE COM VOCÊS / NÃO QUERER NINGUÉM PERECER / QUERER TODOS ARREPENDER-SE.\n(CENA: DIA DO SENHOR)\nDIA DO SENHOR VIR COMO LADRÃO / DE SURPRESA.\nCÉUS DESAPARECER COM GRANDE ESTRONDO / ELEMENTOS DISSOLVER FOGO / TERRA E OBRAS SER CONSUMIDAS [CONFORME TEXTO LITÚRGICO IMPORTADO].\nPOR ISSO / COMO VOCÊS PRECISAR VIVER?\nVIDA SANTA / DEVOÇÃO / ESPERAR VINDA DIA DE DEUS.\nCÉUS DISSOLVER CHAMAS / ELEMENTOS DERRETER PELO CALOR.\nNÓS ESPERAR PROMESSA DE DEUS / NOVOS CÉUS E NOVA TERRA / JUSTIÇA HABITAR.\nENQUANTO ESPERAR / ESFORÇAR VIDA SEM PECADO E SEM REPROVAÇÃO / DEUS ENCONTRAR VOCÊS EM PAZ.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|ADVENTO|2º Domingo|evangelho|Mc 1,1-8": "(ROTEIRO EDITORIAL — NARRADOR, PROFECIA E JOÃO BATISTA)\nNARRADOR: COMEÇO EVANGELHO JESUS CRISTO / FILHO DE DEUS.\nPROFETA ISAÍAS REGISTRAR: EU ENVIAR MEU MENSAGEIRO À TUA FRENTE / PREPARAR CAMINHO.\nVOZ CLAMAR NO DESERTO: PREPARAR CAMINHO SENHOR / ENDIREITAR ESTRADAS.\n(CENA: DESERTO E RIO JORDÃO)\nJOÃO BATISTA APARECER DESERTO / PROCLAMAR BATISMO DE CONVERSÃO PARA PERDÃO PECADOS.\nPOVO JUDEIA E JERUSALÉM / IR AO RIO JORDÃO / CONFESSAR PECADOS / JOÃO BATIZAR.\nJOÃO VESTIR ROUPA PELOS CAMELO / CINTO COURO / COMER GAFANHOTOS E MEL SILVESTRE.\n(CENA: JOÃO ANUNCIA JESUS)\nJOÃO: DEPOIS DE MIM / VIR ALGUÉM MAIS FORTE QUE EU.\nEU NEM DIGNO ABAIXAR PARA DESAMARRAR SANDÁLIAS DELE.\nEU BATIZAR VOCÊS COM ÁGUA / ELE BATIZAR VOCÊS COM ESPÍRITO SANTO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|ADVENTO|3º Domingo|primeira-leitura|Is 61,1-2.10-11": "(ROTEIRO EDITORIAL — UNGIDO FALA EM PRIMEIRA PESSOA; mudança para alegria pessoal e imagem da terra)\nESPÍRITO DO SENHOR ESTAR SOBRE MIM / SENHOR ME UNGIR / ENVIAR.\nPARA POBRES / BOA NOTÍCIA ANUNCIAR.\nPARA PESSOAS COM CORAÇÃO AFLITO / CONSOLAR E CURAR.\nPESSOAS CATIVAS / ANUNCIAR LIBERTAÇÃO.\nPESSOAS PRESAS / ANUNCIAR LIBERDADE.\nANO DA GRAÇA DO SENHOR / PROCLAMAR.\n(CENA: ALEGRIA NO SENHOR)\nEU ALEGRAR MUITO NO SENHOR / MINHA ALMA ALEGRAR EM DEUS.\nELE ME VESTIR SALVAÇÃO / ENVOLVER MANTO JUSTIÇA.\nCOMO NOIVO ADORNAR CABEÇA / NOIVA USAR JOIAS.\n(CENA: JUSTIÇA GERMINA)\nCOMO TERRA BROTAR PLANTAS / JARDIM FAZER SEMENTES GERMINAR.\nASSIM SENHOR DEUS / DIANTE TODAS NAÇÕES / JUSTIÇA E LOUVOR FAZER CRESCER.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|ADVENTO|3º Domingo|segunda-leitura|1Ts 5,16-24": "(ROTEIRO EDITORIAL — PAULO AOS TESSALONICENSES)\nIRMÃOS / SEMPRE ALEGRES.\nORAR SEM PARAR / EM TODAS CIRCUNSTÂNCIAS AGRADECER.\nESSA VONTADE DE DEUS PARA VOCÊS EM CRISTO JESUS.\nESPÍRITO NÃO APAGAR / DONS PROFÉTICOS NÃO DESPREZAR.\nTUDO EXAMINAR / O QUE BOM CONSERVAR / TODA FORMA MAL AFASTAR.\n(CENA: BÊNÇÃO)\nDEUS DA PAZ / SANTIFICAR VOCÊS COMPLETAMENTE.\nESPÍRITO / ALMA / CORPO / VOCÊS INTEIROS CONSERVAR SEM REPROVAÇÃO ATÉ VINDA DE JESUS CRISTO.\nDEUS QUE CHAMOU VOCÊS / É FIEL / ELE MESMO CUMPRIR PROMESSA.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|ADVENTO|3º Domingo|evangelho|Jo 1,6-8.19-28": "(ROTEIRO EDITORIAL — NARRADOR, JOÃO BATISTA E ENVIADOS DE JERUSALÉM; JOÃO NÃO É A LUZ)\nNARRADOR: DEUS ENVIAR HOMEM / NOME JOÃO.\nJOÃO VIR COMO TESTEMUNHA DA LUZ / PARA PESSOAS ACREDITAR.\nJOÃO NÃO SER LUZ / TESTEMUNHAR SOBRE LUZ.\n(CENA: DELEGAÇÃO DE JERUSALÉM)\nLÍDERES JUDEUS DE JERUSALÉM / ENVIAR SACERDOTES E LEVITAS PERGUNTAR JOÃO:\nQUEM VOCÊ?\nJOÃO RESPONDER SEM NEGAR: EU NÃO SOU MESSIAS.\nENVIADOS: VOCÊ ELIAS? JOÃO: NÃO.\nENVIADOS: VOCÊ PROFETA? JOÃO: NÃO.\nENVIADOS: ENTÃO QUEM VOCÊ? PRECISAMOS RESPONDER QUEM NOS ENVIOU.\nJOÃO: EU VOZ QUE CLAMA NO DESERTO / ENDIREITAR CAMINHO DO SENHOR / CONFORME ISAÍAS.\n(CENA: FARISEUS QUESTIONAM O BATISMO)\nENVIADOS ENTRE ELES FARISEUS / PERGUNTAR:\nSE NÃO SER MESSIAS, ELIAS NEM PROFETA / POR QUE BATIZAR?\nJOÃO: EU BATIZAR COM ÁGUA.\nMAS ALGUÉM JÁ ESTAR ENTRE VOCÊS / VOCÊS NÃO CONHECER.\nELE VIR DEPOIS DE MIM / MAS EU NEM DIGNO DESAMARRAR CORREIAS SANDÁLIA DELE.\nNARRADOR: ISSO ACONTECER BETÂNIA / ALÉM RIO JORDÃO / ONDE JOÃO BATIZAR.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|ADVENTO|4º Domingo|primeira-leitura|2Sm 7,1-5.8-11.16": "(ROTEIRO EDITORIAL — DAVID, NATÃ E VOZ DE DEUS. 'CASA' ALTERNA MORADIA E DINASTIA.)\n(CENA 1: PALÁCIO DE DAVID)\nDAVI REI / MORAR CASA CEDRO / PAZ DE INIMIGOS.\nDAVI FALAR NATÃ PROFETA: EU MORAR CASA CEDRO / MAS ARCA DE DEUS ESTAR TENDA.\nNATÃ: PODE FAZER O QUE DESEJA / DEUS ESTAR COM VOCÊ.\n(CENA 2: DEUS FALA A NATÃ À NOITE)\nDEUS DIZER NATÃ: VAI DIZER DAVI MEU SERVO.\nVOCÊ QUER CONSTRUIR CASA PARA MIM?\nEU TIREI VOCÊ DO PASTO / DE CUIDAR REBANHOS / FAZER VOCÊ CHEFE MEU POVO ISRAEL.\nEU ESTAR COM VOCÊ EM TODOS LUGARES / DERROTAR INIMIGOS / DAR NOME IMPORTANTE.\n(CENA 3: PROMESSA AO POVO)\nMEU POVO ISRAEL / EU PREPARAR LUGAR / ELES HABITAR COM SEGURANÇA.\nPESSOAS MÁS / NÃO OPRIMIR COMO ANTES / DESCANSO DOS INIMIGOS.\n(CENA 4: DEUS PROMETE UMA DINASTIA)\nDEUS: EU MESMO FAREI UMA CASA PARA VOCÊ / CASA SIGNIFICAR DESCENDÊNCIA REINANTE.\nDEPOIS SUA MORTE / SEU DESCENDENTE REINAR / EU FIRMAR REINO DELE.\nEU SER PARA ELE PAI / ELE PARA MIM FILHO.\nSUA CASA / REINO / TRONO PERMANECER FIRMES PARA SEMPRE DIANTE DE MIM.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|ADVENTO|4º Domingo|segunda-leitura|Rm 16,25-27": "(ROTEIRO EDITORIAL — DOXOLOGIA: PAULO LOUVA A DEUS)\nDEUS TER PODER DE FORTALECER VOCÊS.\nCONFORME EVANGELHO QUE PAULO ANUNCIAR / PREGAÇÃO DE JESUS CRISTO.\nMISTÉRIO MUITO TEMPO ESCONDIDO / AGORA DEUS REVELAR.\nPELAS ESCRITURAS PROFETAS / POR ORDEM DEUS ETERNO / MISTÉRIO FICAR CONHECIDO ENTRE TODOS POVOS.\nOBJETIVO: TODOS POVOS RESPONDER COM OBEDIÊNCIA DA FÉ.\nDEUS ÚNICO / SABEDORIA PERFEITA / POR JESUS CRISTO / RECEBER GLÓRIA PARA SEMPRE.\nAMÉM.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|ADVENTO|4º Domingo|evangelho|Lc 1,26-38": "(ROTEIRO EDITORIAL — ANUNCIAÇÃO; REFERENTES MARIA, GABRIEL, JOSÉ, ISABEL)\n(CENA 1: GABRIEL CHEGA EM NAZARÉ)\nDEUS ENVIAR ANJO GABRIEL / CIDADE NAZARÉ NA GALILEIA.\nGABRIEL IR ENCONTRAR VIRGEM MARIA / PROMETIDA EM CASAMENTO A JOSÉ / JOSÉ DESCENDENTE DAVID.\nGABRIEL: ALEGRA-TE CHEIA DE GRAÇA / SENHOR ESTÁ COM VOCÊ.\nMARIA SURPRESA / PENSAR SOBRE SAUDAÇÃO.\n(CENA 2: GABRIEL ANUNCIA O FILHO)\nANJO: MARIA / NÃO TER MEDO / DEUS CONCEDER GRAÇA.\nVOCÊ CONCEBER / DAR À LUZ FILHO / NOME DELE JESUS.\nELE GRANDE / CHAMADO FILHO DO ALTÍSSIMO.\nSENHOR DEUS DAR A ELE TRONO DE DAVID / REINAR PARA SEMPRE SOBRE CASA DE JACÓ / REINO NÃO TER FIM.\n(CENA 3: PERGUNTA DE MARIA)\nMARIA: COMO ACONTECER / EU NÃO CONHECER HOMEM?\nGABRIEL: ESPÍRITO SANTO VIR SOBRE VOCÊ / PODER ALTÍSSIMO COBRIR COM SUA SOMBRA.\nPOR ISSO CRIANÇA SANTA QUE NASCER / CHAMADA FILHO DE DEUS.\nSUA PARENTE ISABEL / GRÁVIDA NA VELHICE / JÁ SEXTO MÊS / ANTES CONSIDERADA ESTÉRIL.\nPARA DEUS NADA IMPOSSÍVEL.\n(CENA 4: RESPOSTA DE MARIA)\nMARIA: EU SERVA DO SENHOR / ACONTEÇA EM MIM CONFORME SUA PALAVRA.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|17º Domingo|evangelho|Jo 6,1-15": "(ROTEIRO EDITORIAL — JESUS, FILIPE, ANDRÉ, MENINO, MULTIDÃO; distinguir milagre e tentativa de fazê-lo rei)\n(CENA 1: JESUS ATRAVESSA MAR DA GALILEIA)\nJESUS IR OUTRO LADO MAR GALILEIA / TIBERÍADES.\nMULTIDÃO GRANDE SEGUIR JESUS / VIR CURAS DOENTES.\nJESUS SUBIR MONTE / SENTAR COM DISCÍPULOS / PÁSCOA DOS JUDEUS ESTAR PRÓXIMA.\n(CENA 2: PERGUNTA A FILIPE)\nJESUS VER MULTIDÃO CHEGANDO / PERGUNTAR FILIPE:\nONDE COMPRAR PÃO PARA TODOS COMER?\nJESUS JÁ SABER O QUE VAI FAZER / PERGUNTAR PARA PROVAR FILIPE.\nFILIPE: DUZENTOS DENÁRIOS / NÃO BASTAR PARA CADA PESSOA UM POUCO PÃO.\n(CENA 3: ANDRÉ E O MENINO)\nANDRÉ IRMÃO PEDRO: AQUI MENINO TER CINCO PÃES CEVADA E DOIS PEIXES.\nMAS PARA MULTIDÃO / ISSO MUITO POUCO.\nJESUS: MANDAR PESSOAS SENTAR.\nMUITA GRAMA / HOMENS CERCA CINCO MIL.\n(CENA 4: DISTRIBUIÇÃO)\nJESUS PEGAR PÃES / AGRADECER A DEUS / DISTRIBUIR A TODOS SENTADOS.\nPEIXES TAMBÉM DISTRIBUIR / TODOS COMER QUANTO QUISER.\nTODOS SATISFEITOS / JESUS MANDAR DISCÍPULOS JUNTAR SOBRAS / NADA DESPERDIÇAR.\nSOBRAS DOS CINCO PÃES / ENCHER DOZE CESTOS.\n(CENA 5: RESPOSTA DA MULTIDÃO)\nPESSOAS VER MILAGRE / DIZER JESUS É PROFETA QUE VIRIA AO MUNDO.\nJESUS SABER MULTIDÃO QUERER FAZÊ-LO REI À FORÇA / AFASTAR-SE / VOLTAR MONTE SOZINHO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|18º Domingo|evangelho|Jo 6,24-35": "(ROTEIRO EDITORIAL — DISCURSO DO PÃO DA VIDA; distinguir pão material, maná e JESUS como PÃO VERDADEIRO)\n(CENA 1: MULTIDÃO PROCURA JESUS)\nMULTIDÃO PERCEBER JESUS E DISCÍPULOS NÃO ESTAR MARGEM LAGO.\nPESSOAS ENTRAR BARCOS / IR CAFARNAUM / PROCURAR JESUS.\nENCONTRAR JESUS OUTRO LADO / PERGUNTAR: MESTRE / QUANDO VOCÊ CHEGOU?\n(CENA 2: JESUS QUESTIONA MOTIVAÇÃO)\nJESUS: VERDADE EU DIGO / VOCÊS ME PROCURAR PORQUE COMER PÃES ATÉ SATISFAZER / NÃO POR ENTENDER SINAL.\nTRABALHAR NÃO SÓ POR ALIMENTO QUE ACABA / BUSCAR ALIMENTO PARA VIDA ETERNA.\nFILHO DO HOMEM DAR ESSE ALIMENTO / DEUS PAI MARCAR ELE COM SELO.\n(CENA 3: FÉ E OBRAS)\nPOVO: QUE FAZER PARA PRATICAR OBRAS DE DEUS?\nJESUS: OBRA DE DEUS / ACREDITAR NAQUELE QUE DEUS ENVIOU.\n(CENA 4: MANÁ E PÃO DO CÉU)\nPOVO: QUAL SINAL VOCÊ FAZER PARA NÓS CRERMOS?\nNOSSOS ANTEPASSADOS / DESERTO / COMER MANÁ / PÃO QUE VEIO DO CÉU.\nJESUS: NÃO MOISÉS DAR PÃO VERDADEIRO DO CÉU / MEU PAI DAR AGORA.\nPÃO DE DEUS DESCER CÉU / DAR VIDA AO MUNDO.\nPOVO: SENHOR / SEMPRE ESSE PÃO NOS DAR.\n(CENA 5: REVELAÇÃO)\nJESUS: EU SOU PÃO DA VIDA.\nQUEM VIR A MIM / NÃO TERÁ FOME / QUEM CRER EM MIM / NÃO TERÁ SEDE.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|19º Domingo|evangelho|Jo 6,41-51": "(ROTEIRO EDITORIAL — murmuração, envio do Pai, ressurreição e pão vivo)\n(CENA 1: PESSOAS MURMURAM)\nJESUS DIZER: EU PÃO DESCIDO CÉU.\nALGUMAS PESSOAS QUESTIONAR: ESSE NÃO SER JESUS FILHO JOSÉ?\nNÓS CONHECER PAI E MÃE DELE / COMO ELE DIZER DESCER CÉU?\n(CENA 2: JESUS RESPONDE)\nJESUS: NÃO MURMURAR.\nNENHUMA PESSOA VIR ATÉ MIM / SE PAI QUE ME ENVIOU NÃO ATRAIR.\nQUEM VIER / NO ÚLTIMO DIA EU RESSUSCITAR.\nPROFETAS DIZER: TODOS SERÃO ENSINADOS POR DEUS.\nQUEM OUVIR PAI / ACEITAR ENSINAMENTO DELE / VIR A MIM.\nNINGUÉM VER PAI / EXCETO AQUELE QUE VEIO DE DEUS.\n(CENA 3: VIDA ETERNA)\nJESUS: VERDADE EU DIGO / QUEM CRER TEM VIDA ETERNA.\nEU SOU PÃO DA VIDA.\nANTEPASSADOS DE VOCÊS COMER MANÁ NO DESERTO / DEPOIS MORRER.\nPÃO QUE DESCE CÉU / QUEM COMER NÃO MORRER ESPIRITUALMENTE.\nEU SOU PÃO VIVO QUE DESCEU CÉU / QUEM COMER / VIVER PARA SEMPRE.\nPÃO QUE EU DAREI / MINHA CARNE / ENTREGUE PARA VIDA DO MUNDO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|20º Domingo|evangelho|Jo 6,51-58": "(ROTEIRO EDITORIAL — ENSINO SOBRE A CARNE E O SANGUE DE CRISTO; não trocar por explicação metafórica exclusivamente)\nJESUS FALAR MULTIDÃO:\nEU SOU PÃO VIVO QUE DESCEU CÉU / QUEM COMER DESSE PÃO / VIVER PARA SEMPRE.\nPÃO QUE EU DAREI / MINHA CARNE / ENTREGAREI PELA VIDA DO MUNDO.\n(CENA 1: QUESTIONAMENTO)\nALGUMAS PESSOAS DISCUTIR ENTRE SI:\nCOMO JESUS PODER NOS DAR SUA CARNE PARA COMER?\n(CENA 2: JESUS INSISTE NO ENSINAMENTO)\nJESUS: VERDADE EU DIGO.\nSE NÃO COMER CARNE FILHO DO HOMEM / NÃO BEBER SEU SANGUE / NÃO TER VIDA EM VOCÊS.\nQUEM COMER MINHA CARNE E BEBER MEU SANGUE / TER VIDA ETERNA.\nNO ÚLTIMO DIA / EU RESSUSCITAR ESSA PESSOA.\nMINHA CARNE VERDADEIRA COMIDA / MEU SANGUE VERDADEIRA BEBIDA.\nQUEM COMER MINHA CARNE E BEBER MEU SANGUE / PERMANECER EM MIM / EU PERMANECER NELE.\n(CENA 3: RELAÇÃO COM PAI)\nDEUS PAI VIVO / ELE ME ENVIOU / EU VIVER POR CAUSA PAI.\nQUEM RECEBER-ME COMO ALIMENTO / VIVERÁ POR MIM.\nESSE É PÃO DESCIDO DO CÉU.\nNÃO COMO MANÁ QUE ANTEPASSADOS COMER E MORRER.\nQUEM COMER ESSE PÃO / VIVER PARA SEMPRE.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|21º Domingo|evangelho|Jo 6,60-69": "(ROTEIRO EDITORIAL — DISCÍPULOS QUE SE AFASTAM, JESUS E SIMÃO PEDRO)\n(CENA 1: DISCÍPULOS REAGEM)\nMUITOS DISCÍPULOS OUVIR ENSINO JESUS / DIZER:\nESSAS PALAVRAS DIFÍCEIS / QUEM PODER ACEITAR?\nJESUS SABER PESSOAS MURMURAR / PERGUNTAR: ISSO OFENDER VOCÊS?\nE SE VOCÊS VEREM FILHO DO HOMEM SUBIR PARA ONDE ESTAVA ANTES?\nESPÍRITO É QUEM DÁ VIDA / CARNE SOZINHA NÃO PRODUZ VIDA.\nPALAVRAS QUE EU DIZER / SÃO ESPÍRITO E VIDA.\nMAS ALGUNS AQUI / NÃO ACREDITAR.\nNARRADOR: JESUS DESDE INÍCIO SABER QUEM NÃO CRER E QUEM IR ENTREGÁ-LO.\nJESUS: POR ISSO EU DIGO / NINGUÉM PODE VIR A MIM / SE PAI NÃO CONCEDER.\n(CENA 2: SEPARAÇÃO)\nMUITOS DISCÍPULOS AFASTAR-SE / DEIXAR CAMINHAR COM JESUS.\n(CENA 3: DECISÃO DOS DOZE)\nJESUS PERGUNTAR DOZE: VOCÊS TAMBÉM QUEREM IR EMBORA?\nSIMÃO PEDRO RESPONDER: SENHOR / NÓS IR A QUEM?\nTU TER PALAVRAS DE VIDA ETERNA.\nNÓS ACREDITAMOS / SABEMOS TU ÉS O SANTO DE DEUS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|QUARESMA|3º Domingo|evangelho|Jo 2,13-25": "(ROTEIRO EDITORIAL — início do texto importado contém aclamação antes do EVANGELHO; distinguir os dois)\n(CENA 1: JESUS CHEGA A JERUSALÉM)\nPÁSCOA DOS JUDEUS PRÓXIMA / JESUS IR JERUSALÉM.\nNO TEMPLO / ENCONTRAR PESSOAS VENDENDO BOIS / OVELHAS / POMBAS / OUTRAS TROCAR DINHEIRO.\n(CENA 2: ZELO PELA CASA DO PAI)\nJESUS FAZER CHICOTE COM CORDAS / EXPULSAR COMERCIANTES E ANIMAIS.\nDINHEIRO CAMBISTAS ESPALHAR / MESAS DERRUBAR.\nA QUEM VENDER POMBAS / JESUS DIZER:\nTIREM ISSO DAQUI / CASA MEU PAI NÃO PODE VIRAR LOCAL COMÉRCIO.\nDISCÍPULOS LEMBRAR ESCRITURA: ZELO PELA TUA CASA ME CONSOME.\n(CENA 3: PERGUNTAM POR UM SINAL)\nLÍDERES JUDEUS: QUE SINAL VOCÊ MOSTRAR / PARA TER DIREITO FAZER ISSO?\nJESUS: DESTRUAM ESTE TEMPLO / TRÊS DIAS DEPOIS EU LEVANTAREI.\nLÍDERES: TEMPLO CONSTRUÍDO DURANTE QUARENTA E SEIS ANOS / VOCÊ LEVANTAR EM TRÊS DIAS?\nNARRADOR EXPLICAR: JESUS FALAR TEMPLO DO SEU PRÓPRIO CORPO / SUA RESSURREIÇÃO.\nDEPOIS JESUS RESSUSCITAR / DISCÍPULOS LEMBRAR SUAS PALAVRAS / CRER ESCRITURA.\n(CENA 4: JESUS CONHECE AS PESSOAS)\nDURANTE FESTA PÁSCOA EM JERUSALÉM / MUITOS VER SINAIS JESUS / CRER.\nMAS JESUS CONHECER CORAÇÃO DE TODOS / NÃO PRECISAR OUTRAS PESSOAS EXPLICAREM O INTERIOR HUMANO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|QUARESMA|4º Domingo|evangelho|Jo 3,14-21": "(ROTEIRO EDITORIAL — JESUS FALA A NICODEMOS; Moisés/serpente no deserto é prefiguração da elevação de Cristo)\n(CENA 1: ELEVAÇÃO)\nJESUS → NICODEMOS: MOISÉS NO DESERTO / LEVANTAR SERPENTE.\nASSIM FILHO DO HOMEM SER ELEVADO / PARA QUEM CRER NELE TER VIDA ETERNA.\n(CENA 2: AMOR E SALVAÇÃO)\nDEUS AMAR MUNDO TANTO / ENTREGAR SEU FILHO ÚNICO.\nQUEM CRER NELE / NÃO PERECER / RECEBER VIDA ETERNA.\nDEUS NÃO ENVIAR FILHO PARA CONDENAR MUNDO / MAS PARA SALVAR MUNDO POR ELE.\nQUEM CRER / NÃO SER CONDENADO.\nQUEM NÃO CRER NO NOME FILHO ÚNICO / JÁ SOB JUÍZO POR SUA INCREDULIDADE.\n(CENA 3: LUZ E TREVAS)\nLUZ VERDADEIRA VIR MUNDO / MAS ALGUMAS PESSOAS PREFERIR TREVAS.\nPOR QUÊ? OBRAS DELAS MÁS / NÃO QUEREM QUE SEJAM MOSTRADAS.\nQUEM PRATICAR MAL / EVITAR LUZ / PARA AÇÕES NÃO SEREM REVELADAS.\nQUEM VIVER NA VERDADE / APROXIMAR LUZ / SUAS AÇÕES MOSTRAR QUE FORAM FEITAS EM DEUS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|QUARESMA|5º Domingo|evangelho|Jo 12,20-33": "(ROTEIRO EDITORIAL — GREGOS, FILIPE, ANDRÉ, JESUS, VOZ DO CÉU, MULTIDÃO)\n(CENA 1: PEREGRINOS GREGOS)\nALGUNS GREGOS CHEGAR JERUSALÉM PARA FESTA / QUERER VER JESUS.\nIR FALAR FILIPE: SENHOR / NÓS QUEREMOS VER JESUS.\nFILIPE CONTAR ANDRÉ / OS DOIS IR FALAR JESUS.\n(CENA 2: HORA DO FILHO DO HOMEM)\nJESUS: HORA CHEGAR / FILHO DO HOMEM SER GLORIFICADO.\n(IMAGEM: GRÃO TRIGO)\nSE GRÃO TRIGO CAIR TERRA E NÃO MORRER / CONTINUAR SÓ.\nSE MORRER / GERAR MUITO FRUTO.\nQUEM SE APEGAR À PRÓPRIA VIDA / PERDÊ-LA.\nQUEM ABRIR MÃO DESTA VIDA POR FIDELIDADE A DEUS / GUARDAR VIDA ETERNA.\nQUEM QUERER ME SERVIR / ME SEGUIR.\nONDE EU ESTIVER / MEU SERVO TAMBÉM.\nQUEM ME SERVIR / PAI HONRAR.\n(CENA 3: JESUS SE COMOVE)\nJESUS: AGORA MINHA ALMA ANGUSTIADA.\nQUE FALAR? PAI / LIVRA-ME DESTA HORA?\nMAS EU VIM JUSTAMENTE PARA ESTA HORA.\nPAI / GLORIFICA TEU NOME.\n(CENA 4: VOZ DO CÉU)\nVOZ DO CÉU: EU JÁ GLORIFIQUEI / DE NOVO GLORIFICAREI.\nMULTIDÃO OUVIR / ALGUNS PENSAR TROVÃO / OUTROS DIZER ANJO FALOU.\nJESUS: VOZ SOAR POR CAUSA DE VOCÊS / NÃO POR CAUSA DE MIM.\n(CENA 5: JUÍZO E ELEVAÇÃO)\nJESUS: AGORA JULGAMENTO MUNDO / PRÍNCIPE DESTE MUNDO SER EXPULSO.\nQUANDO EU SER ELEVADO DA TERRA / ATRAIREI TODOS A MIM.\nNARRADOR EXPLICAR: JESUS ASSIM INDICAR SUA FUTURA MORTE.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|PÁSCOA E TEMPO PASCAL|Pentecostes|segunda-leitura|1Cor 12,3-7.12-13": "(ROTEIRO EDITORIAL — DUAS LEITURAS ALTERNATIVAS NO MESMO REGISTRO. Escolher somente a opção proclamada. A SEQUÊNCIA de Pentecostes é texto litúrgico adicional, não parte da leitura paulina.)\n[OPÇÃO 1: 1COR 12,3-7.12-13]\nPAULO → IRMÃOS: NINGUÉM PODE PROFESSAR DE VERDADE 'JESUS É SENHOR' SEM AÇÃO DO ESPÍRITO SANTO.\nEXISTIR DONS DIFERENTES / MAS MESMO ESPÍRITO.\nEXISTIR SERVIÇOS DIFERENTES / MAS MESMO SENHOR.\nEXISTIR ATIVIDADES DIFERENTES / MAS MESMO DEUS REALIZAR TODAS EM TODOS.\nESPÍRITO REVELAR SEUS DONS EM CADA PESSOA / PARA BEM DE TODOS.\nCOMO CORPO HUMANO / UM SÓ / MAS MUITOS MEMBROS.\nCRISTO / UM CORPO COM MUITOS MEMBROS.\nJUDEUS E GREGOS / ESCRAVOS E LIVRES / TODOS RECEBER BATISMO NO MESMO ESPÍRITO / FORMAR UM CORPO.\nTODOS RECEBER MESMO ESPÍRITO.\n[OPÇÃO 2: GL 5,16-25 — LEITURA ALTERNATIVA]\nPAULO → IRMÃOS: VIVAM GUIADOS PELO ESPÍRITO / NÃO SIGAM DESEJOS DESORDENADOS DA CARNE.\nDESEJOS DA CARNE / CONTRÁRIOS AO ESPÍRITO / OS DOIS ENTRAM EM CONFLITO.\nSE ESPÍRITO GUIAR VOCÊS / NÃO FICAR SOB A LEI.\nOBRAS DA CARNE: IMORALIDADE / IDOLATRIA / FEITIÇARIA / INIMIZADES / INVEJA / BRIGAS / DIVISÕES / EMBRIAGUEZ / OUTROS COMPORTAMENTOS SEMELHANTES.\nQUEM PERSISTIR NESSES COMPORTAMENTOS / NÃO HERDAR REINO DE DEUS.\nFRUTOS DO ESPÍRITO: AMOR / ALEGRIA / PAZ / PACIÊNCIA / AMABILIDADE / BONDADE / FIDELIDADE / MANSIDÃO / TEMPERANÇA.\nCONTRA TAIS FRUTOS / LEI NÃO CONDENAR.\nQUEM PERTENCER JESUS CRISTO / RENUNCIAR DESEJOS PECAMINOSOS.\nSE ESPÍRITO NOS FAZ VIVER / CAMINHAR TAMBÉM GUIADOS POR ELE.\n[SEQUÊNCIA DE PENTECOSTES — TEXTO PRÓPRIO]\nNO ARQUIVO-FONTE A SEQUÊNCIA VEM APÓS A LEITURA ALTERNATIVA. PREPARAR-A EM DOCUMENTO/SEÇÃO SEPARADA, NÃO INSERIR SUA GLOSA DENTRO DA LEITURA II.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|PÁSCOA E TEMPO PASCAL|Ascensão do Senhor|segunda-leitura|Ef 1,17-23": "(ROTEIRO EDITORIAL — DUAS LEITURAS ALTERNATIVAS NO MESMO REGISTRO. Escolher somente a proclamada.)\n[OPÇÃO 1: EF 1,17-23]\nPAULO PEDIR A DEUS / PAI DE NOSSO SENHOR JESUS CRISTO / PAI DA GLÓRIA:\nDAR A VOCÊS SABEDORIA E REVELAÇÃO PARA CONHECER DEUS.\nILUMINAR OLHOS CORAÇÃO / COMPREENDER ESPERANÇA DO CHAMADO DE DEUS.\nCOMPREENDER RIQUEZA HERANÇA ENTRE SANTOS / GRANDE PODER DE DEUS PARA QUEM CRÊ.\nDEUS MOSTRAR ESSE PODER QUANDO RESSUSCITAR CRISTO DOS MORTOS.\nDEUS COLOCAR CRISTO À SUA DIREITA NO CÉU.\nCRISTO ACIMA DE TODOS PRINCIPADOS / PODERES / AUTORIDADES / NOMES / PRESENTES E FUTUROS.\nDEUS SUBMETER TUDO A CRISTO / ELE CABEÇA DA IGREJA.\nIGREJA / CORPO DE CRISTO / CRISTO A PREENCHE E DÁ PLENITUDE.\n[OPÇÃO 2: EF 4,1-13]\nPAULO / PRESO POR CAUSA DO SENHOR / PEDIR CRISTÃOS: VIVAM CONFORME CHAMADO DE DEUS.\nHUMILDADE / MANSIDÃO / PACIÊNCIA / SUPORTAR UNS AOS OUTROS COM AMOR.\nESFORÇAR MANTER UNIDADE DO ESPÍRITO POR VÍNCULO PAZ.\nUM CORPO / UM ESPÍRITO / UMA ESPERANÇA.\nUM SENHOR / UMA FÉ / UM BATISMO / UM DEUS PAI DE TODOS.\nCRISTO DAR GRAÇA DIFERENTE A CADA UM.\nESCRITURA FALAR SUBIDA E DESCIDA / CRISTO SUBIR ACIMA CÉUS PARA ENCHER UNIVERSO.\nELE CHAMAR ALGUNS APÓSTOLOS / OUTROS EVANGELISTAS / PASTORES E MESTRES.\nOBJETIVO: PREPARAR CRISTÃOS PARA SERVIÇO / CONSTRUIR CORPO DE CRISTO.\nATÉ TODOS ALCANÇAR UNIDADE DA FÉ / CONHECIMENTO DO FILHO DE DEUS / MATURIDADE / PLENITUDE DE CRISTO.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|Domingo de Ramos e da Paixão|procissao|Mc 11,1-10 ou Jo 12,12-16": "(ROTEIRO EDITORIAL — PROCISSÃO DE RAMOS. DUAS OPÇÕES: NÃO PROCLAMAR AS DUAS COMO SE FOSSEM UMA.)\n[OPÇÃO 1: MC 11,1-10]\n(CENA 1: JESUS APROXIMA JERUSALÉM / BETFAGÉ / BETÂNIA / MONTE OLIVEIRAS)\nJESUS ENVIAR DOIS DISCÍPULOS AO POVOADO.\nJESUS: LOGO ENTRADA / JUMENTINHO AMARRADO / NINGUÉM AINDA MONTOU / DESAMARRAR E TRAZER.\nSE ALGUÉM PERGUNTAR / DIZER SENHOR PRECISA / EM BREVE DEVOLVER.\nDISCÍPULOS ENCONTRAR JUMENTINHO NA RUA / DESAMARRAR.\nPESSOAS PERGUNTAR POR QUE / DISCÍPULOS EXPLICAR / DEIXAM LEVAR.\n(CENA 2: ENTRADA TRIUNFAL)\nDISCÍPULOS COLOCAR CAPAS SOBRE JUMENTINHO / JESUS MONTAR.\nMUITOS ESPALHAR CAPAS NO CAMINHO / OUTROS RAMOS CORTADOS.\nPESSOAS NA FRENTE E ATRÁS GRITAR:\nHOSANA! BENDITO AQUELE QUE VEM EM NOME DO SENHOR!\nBENDITO REINO QUE VEM / REINO DE NOSSO PAI DAVID!\nHOSANA NAS ALTURAS!\n[OPÇÃO 2: JO 12,12-16]\n(CENA 1: MULTIDÃO PEREGRINA)\nPOVO NA FESTA PÁSCOA / SABER JESUS CHEGAR JERUSALÉM.\nPEGAR RAMOS PALMEIRAS / IR ENCONTRAR JESUS / ACLAMAR:\nHOSANA! BENDITO AQUELE QUE VEM EM NOME DO SENHOR / REI ISRAEL!\n(CENA 2: PROFECIA)\nJESUS ENCONTRAR JUMENTINHO / MONTAR.\nESCRITURA: POVO SIÃO / NÃO TEMER / TEU REI VEM MONTADO FILHO JUMENTA.\nDISCÍPULOS NAQUELE MOMENTO NÃO ENTENDER.\nDEPOIS JESUS GLORIFICADO / DISCÍPULOS LEMBRAR ESCRITURA / RECONHECER ACONTECIMENTO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|QUARESMA|Domingo de Ramos e da Paixão|paixao|Mc 14,1–15,47": "(ROTEIRO NARRATIVO EXPANDIDO — PAIXÃO SEGUNDO MARCOS. NÃO SUBSTITUI REVISÃO INTEGRAL FALA A FALA. USAR N=NARRADOR; J=JESUS; R=OUTROS PERSONAGENS.)\n(CENA 1: PLANO PARA MATAR JESUS)\nN: DOIS DIAS ANTES PÁSCOA / CHEFES SACERDOTES E ESCRIBAS / PLANEJAR PRENDER JESUS À TRAIÇÃO / MATAR.\nR: DURANTE FESTA NÃO / PODE HAVER TUMULTO.\n(CENA 2: MULHER E PERFUME EM BETÂNIA)\nN: JESUS CASA SIMÃO LEPROSO / MULHER CHEGAR / QUEBRAR VASO PERFUME CARO / DERRAMAR NA CABEÇA JESUS.\nR: ALGUNS RECLAMAR DESPERDÍCIO / DINHEIRO PODIA AJUDAR POBRES.\nJ: DEIXAR MULHER EM PAZ / ELA FEZ OBRA BOA.\nJ: POBRES SEMPRE VOCÊS PODEM AJUDAR / EU NÃO ESTAREI SEMPRE.\nJ: ELA PREPARAR MEU CORPO PARA SEPULTAMENTO / AÇÃO SERÁ LEMBRADA ONDE EVANGELHO FOR PREGADO.\n(CENA 3: JUDAS E PREPARAÇÃO DA CEIA)\nN: JUDAS ISCARIOTES / UM DOS DOZE / COMBINAR ENTREGAR JESUS / PROMESSA DINHEIRO.\nN: DISCÍPULOS PERGUNTAR ONDE PREPARAR PÁSCOA.\nJ: DOIS IR CIDADE / ENCONTRAR HOMEM COM JARRO ÁGUA / SEGUIR / PEDIR SALA ALTA / PREPARAR.\nN: DISCÍPULOS ENCONTRAR TUDO COMO JESUS DIZER.\n(CENA 4: CEIA)\nJ: UM DE VOCÊS ME ENTREGARÁ.\nR: DISCÍPULOS PERGUNTAR TRISTES: SOU EU?\nJ: UM DOS DOZE QUE COME COMIGO / FILHO DO HOMEM CUMPRIR ESCRITURA / MAS AI DAQUELE QUE TRAIR.\nN: JESUS TOMAR PÃO / ABENÇOAR / PARTIR / DAR.\nJ: TOMEM / ISTO MEU CORPO.\nN: JESUS TOMAR CÁLICE / DAR GRAÇAS / ENTREGAR / TODOS BEBER.\nJ: ISTO MEU SANGUE DA ALIANÇA / DERRAMADO PELA MULTIDÃO.\nJ: NOVO VINHO / BEBEREI NO REINO DE DEUS.\n(CENA 5: PEDRO E MONTE OLIVEIRAS)\nN: CANTAR SALMOS / IR MONTE DAS OLIVEIRAS.\nJ: VOCÊS ME ABANDONARÃO / PASTOR FERIDO / OVELHAS DISPERSAR.\nJ: DEPOIS RESSUSCITAR / IREI ANTES VOCÊS PARA GALILEIA.\nR (PEDRO): EU NÃO ABANDONAR.\nJ: HOJE À NOITE / GALO CANTAR DUAS VEZES / VOCÊ ME NEGARÁ TRÊS VEZES.\n(CENA 6: GETSÊMANI)\nN: JESUS LEVAR PEDRO, TIAGO, JOÃO / TRISTE E ANGUSTIADO / PEDIR VIGIAR.\nJ → PAI: ABBA / PAI / TUDO TE POSSÍVEL / AFASTAR CÁLICE / MAS TUA VONTADE / NÃO MINHA.\nN: JESUS ORAR / DISCÍPULOS DORMIR / JESUS DESPERTAR / DIZER VIGIAR E ORAR.\nN: SEGUNDA E TERCEIRA VEZ / DISCÍPULOS DORMIR / JESUS ORAR / ANUNCIAR HORA CHEGOU.\n(CENA 7: PRISÃO)\nN: JUDAS CHEGAR COM HOMENS ARMADOS / BEIJAR JESUS COMO SINAL / JESUS PRESO.\nN: ALGUÉM COM ESPADA / CORTAR ORELHA SERVO SUMO SACERDOTE.\nJ: POR QUE ARMAS COMO PARA LADRÃO? EU TODO DIA ENSINAR TEMPLO / CUMPRIR ESCRITURA.\nN: DISCÍPULOS FUGIR / JOVEM COM LENÇOL / FUGIR NU DEIXANDO LENÇOL.\n(CENA 8: SINÉDRIO)\nN: JESUS LEVADO SUMO SACERDOTE / TESTEMUNHAS CONTRADITÓRIAS / ACUSAR SOBRE TEMPLO.\nR (SUMO SACERDOTE): VOCÊ É MESSIAS / FILHO DE DEUS BENDITO?\nJ: EU SOU / FILHO DO HOMEM À DIREITA DO PODER / VIR NAS NUVENS.\nN: SUMO SACERDOTE RASGAR ROUPAS / ACUSAR BLASFÊMIA / CONDENAR JESUS / CUSPIR E AGREDIR.\n(CENA 9: PEDRO NEGA)\nN: SERVA PERGUNTAR PEDRO SE CONHECE JESUS / ELE NEGAR.\nN: NOVA ACUSAÇÃO / PEDRO NEGAR SEGUNDA VEZ.\nN: OUTROS DIZER PEDRO GALILEU / ELE NEGAR TERCEIRA VEZ.\nN: GALO CANTAR SEGUNDA VEZ / PEDRO LEMBRAR PALAVRA JESUS / CHORAR.\n(CENA 10: PILATOS)\nN: CHEFES LEVAR JESUS AMARRADO A PILATOS.\nR (PILATOS): VOCÊ REI JUDEUS?\nJ: VOCÊ DIZ.\nN: JESUS CALADO DIANTE ACUSAÇÕES / PILATOS ADMIRADO.\nN: COSTUME SOLTAR PRESO / BARRABÁS ASSASSINO NA REVOLTA / CHEFES INFLUENCIAR MULTIDÃO.\nR (MULTIDÃO): SOLTAR BARRABÁS / JESUS CRUCIFICAR!\nN: PILATOS LIBERTAR BARRABÁS / JESUS AÇOITADO / ENTREGUE CRUCIFICAÇÃO.\n(CENA 11: SOLDADOS E CAMINHO)\nN: SOLDADOS MANTO PÚRPURA / COROA ESPINHOS / ZOMBAR.\nR: SALVE REI DOS JUDEUS!\nN: BATER E CUSPIR / TIRAR MANTO.\nN: SIMÃO CIRENE PAI ALEXANDRE E RUFO / OBRIGADO CARREGAR CRUZ.\nN: GÓLGOTA / JESUS RECUSAR VINHO COM MIRRA.\n(CENA 12: CRUCIFICAÇÃO)\nN: NOVE HORAS / JESUS CRUCIFICADO / ROUPAS DIVIDIDAS / INSCRIÇÃO REI DOS JUDEUS.\nN: DOIS CRIMINOSOS AO LADO / PESSOAS E LÍDERES ZOMBAR / PEDIR DESCER CRUZ.\n(CENA 13: MORTE)\nN: MEIO DIA ATÉ TRÊS / ESCURIDÃO.\nJ: ELOÍ / ELOÍ / LEMÁ SABACTÁNI? / MEU DEUS / POR QUE ME ABANDONASTE?\nN: ALGUNS ENTENDER CHAMAR ELIAS / OFERECER ESPONJA VINAGRE.\nN: JESUS CLAMAR / MORRER.\n(SILÊNCIO E PAUSA LITÚRGICA OBRIGATÓRIOS)\nN: VÉU TEMPLO RASGAR.\nR (CENTURIÃO): VERDADEIRAMENTE ESTE HOMEM ERA FILHO DE DEUS!\nN: MARIA MADALENA, MARIA MÃE TIAGO E JOSÉ, SALOMÉ E OUTRAS MULHERES / ASSISTIR DE LONGE.\n(CENA 14: SEPULTAMENTO)\nN: JOSÉ ARIMATEIA / MEMBRO SINÉDRIO / PEDIR CORPO JESUS PILATOS.\nN: PILATOS CONSULTAR CENTURIÃO / CONFIRMAR MORTE / AUTORIZAR.\nN: JOSÉ ENVOLVER CORPO EM LENÇOL / DEPOSITAR TÚMULO ROCHA / FECHAR PEDRA.\nN: MARIA MADALENA E OUTRA MARIA / OBSERVAR LOCAL SEPULTAMENTO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)\n(NOTA: PREPARAR CADA FALA DO TEXTO PROCLAMADO / NÃO UTILIZAR COMO SUBSTITUTO DA PAIXÃO INTEGRAL.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Batismo do Senhor|primeira-leitura|Is 42,1-4.6-7": "(ROTEIRO EDITORIAL — DEUS FALA DO SERVO ELEITO; o texto é a leitura proposta no acervo, confirmar variante brasileira antes da celebração)\nDEUS: VEJAM MEU SERVO / EU PROTEJO / EU ESCOLHI / NELE ME AGRADO.\nMEU ESPÍRITO REPOUSAR SOBRE ELE / ELE LEVAR JUSTIÇA A TODAS NAÇÕES.\nELE NÃO GRITAR NEM BUSCAR IMPOR-SE NAS PRAÇAS.\nCANA JÁ PARTIDA / ELE NÃO QUEBRAR / PAVIO QUASE APAGADO / ELE NÃO EXTINGUIR.\nELE ANUNCIAR JUSTIÇA COM FIDELIDADE.\nELE NÃO DESISTIR / ATÉ JUSTIÇA SER ESTABELECIDA TERRA / POVOS DISTANTES ESPERAR SEUS ENSINAMENTOS.\nDEUS: EU SENHOR / CHAMEI VOCÊ COM JUSTIÇA / PEGUEI TUA MÃO / FORMEI VOCÊ.\nFAZER VOCÊ ALIANÇA COM MEU POVO / LUZ PARA NAÇÕES.\nPARA ABRIR OLHOS DE QUEM NÃO VÊ / LIBERTAR PRISIONEIROS / TIRAR PESSOAS DA ESCURIDÃO.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Batismo do Senhor|segunda-leitura|At 10,34-38": "(ROTEIRO EDITORIAL — PEDRO DIRIGE-SE AOS OUVINTES)\nPEDRO: AGORA EU COMPREENDO / DEUS NÃO FAVORECER UM POVO EM DETRIMENTO OUTRO.\nPESSOAS DE QUALQUER NAÇÃO / QUEM RESPEITAR DEUS E PRATICAR JUSTIÇA / AGRADAR A ELE.\nDEUS ENVIAR SUA PALAVRA A FILHOS DE ISRAEL / ANUNCIAR PAZ POR JESUS CRISTO.\nJESUS CRISTO / SENHOR DE TODOS.\nVOCÊS SABER ACONTECIMENTOS POR TODA JUDEIA / COMEÇOU GALILEIA.\nDEPOIS BATISMO QUE JOÃO ANUNCIAR / DEUS UNGIR JESUS DE NAZARÉ COM ESPÍRITO SANTO E PODER.\nJESUS PERCORRER LUGARES / FAZER BEM / CURAR PESSOAS OPRIMIDAS PELO MAL.\nPOR QUÊ? DEUS ESTAR COM JESUS.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Batismo do Senhor|evangelho|Mc 1,7-11": "(ROTEIRO EDITORIAL — PERSONAGENS JOÃO, JESUS E VOZ DO CÉU; DISTINGUIR ESPÍRITO DE POMBA COMO COMPARAÇÃO)\n(CENA 1: JOÃO ANUNCIA)\nJOÃO BATISTA: DEPOIS DE MIM VIR ALGUÉM MAIS FORTE QUE EU.\nEU NÃO SER DIGNO ABAIXAR E DESAMARRAR CORREIAS SANDÁLIA DELE.\nEU BATIZAR VOCÊS COM ÁGUA / ELE BATIZARÁ VOCÊS COM ESPÍRITO SANTO.\n(CENA 2: JESUS VAI AO JORDÃO)\nJESUS VIR DE NAZARÉ DA GALILEIA / JOÃO BATIZAR JESUS NO RIO JORDÃO.\nJESUS SUBIR DA ÁGUA / VER CÉUS ABRIR-SE.\nESPÍRITO DESCER SOBRE JESUS / EM FORMA COMO POMBA.\n(CENA 3: VOZ DO CÉU)\nDEUS PAI (VOZ DO CÉU): VOCÊ É MEU FILHO MUITO AMADO.\nEM VOCÊ / TODA MINHA ALEGRIA E APROVAÇÃO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Vigília|evangelho|Mt 1,1-25": "(ROTEIRO EDITORIAL — verificar se a Missa utilizará a genealogia longa ou a forma breve indicada pela autoridade litúrgica. O texto-fonte aqui importado contém a forma longa.)\n(CENA 1: GENEALOGIA DE JESUS / FAMÍLIA AO LONGO DAS GERAÇÕES)\nJESUS CRISTO / DESCENDENTE DAVID / DESCENDENTE ABRAÃO.\n(GENEALOGIA — preservar a sequência dos nomes quando a forma longa for proclamada)\nABRAÃO PAI ISAAC / ISAAC PAI JACÓ / JACÓ PAI JUDÁ E IRMÃOS.\nJUDÁ E TAMAR / FARÉS E ZARA / FARÉS PAI ESROM / ESROM PAI ARÃO.\nARÃO PAI AMINADAB / AMINADAB PAI NAASSON / NAASSON PAI SALMON.\nSALMON E RAAB / BOOZ / BOOZ E RUTE / OBED / OBED PAI JESSÉ.\nJESSÉ PAI DAVID / DAVID REI.\nDAVID E MULHER DE URIAS / SALOMÃO.\nSALOMÃO PAI ROBOÃO / ROBOÃO PAI ABIAS / ABIAS PAI ASA.\nASA PAI JOSAFAT / JOSAFAT PAI JORÃO / JORÃO PAI OZIAS.\nOZIAS PAI JOATÃO / JOATÃO PAI ACAZ / ACAZ PAI EZEQUIAS.\nEZEQUIAS PAI MANASSÉS / MANASSÉS PAI AMON / AMON PAI JOSIAS.\nJOSIAS PAI JECONIAS E IRMÃOS / TEMPO EXÍLIO BABILÔNIA.\nDEPOIS EXÍLIO BABILÔNIA / JECONIAS PAI SALATIEL / SALATIEL PAI ZOROBABEL.\nZOROBABEL PAI ABIUD / ABIUD PAI ELIACIM / ELIACIM PAI AZOR.\nAZOR PAI SADOC / SADOC PAI AQUIM / AQUIM PAI ELIUD.\nELIUD PAI ELEAZAR / ELEAZAR PAI MATÃ / MATÃ PAI JACÓ.\nJACÓ PAI JOSÉ / JOSÉ MARIDO MARIA / MARIA MÃE JESUS CHAMADO CRISTO.\nABRAÃO ATÉ DAVID / CATORZE GERAÇÕES.\nDAVID ATÉ EXÍLIO BABILÔNIA / CATORZE GERAÇÕES.\nEXÍLIO ATÉ CRISTO / CATORZE GERAÇÕES.\n(CENA 2: MARIA E JOSÉ)\nMARIA NOIVA JOSÉ / ANTES VIVEREM JUNTOS / MARIA GRÁVIDA POR OBRA ESPÍRITO SANTO.\nJOSÉ JUSTO / NÃO QUERER EXPOR MARIA VERGONHA / PENSAR AFASTAR-SE EM SEGREDO.\n(CENA 3: ANJO APARECE EM SONHO)\nANJO DO SENHOR APARECER SONHO JOSÉ.\nANJO: JOSÉ DESCENDENTE DAVID / NÃO TER MEDO RECEBER MARIA COMO ESPOSA.\nFILHO GERADO EM MARIA / ORIGEM ESPÍRITO SANTO.\nMARIA DAR À LUZ MENINO / VOCÊ COLOCAR NOME JESUS.\nELE SALVAR SEU POVO DOS PECADOS.\n(CENA 4: CUMPRIMENTO DA PROFECIA)\nPROFETA ANUNCIAR VIRGEM CONCEBER / DAR À LUZ FILHO.\nNOME EMANUEL / SIGNIFICAR DEUS CONOSCO.\nJOSÉ ACORDAR / OBEDECER ANJO / RECEBER MARIA COMO ESPOSA.\n(ENCERRAMENTO — PALAVRA DA SALVAÇÃO.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Dia|evangelho|Jo 1,1-18": "(ROTEIRO DE PREPARAÇÃO — PRÓLOGO DE JOÃO. VERBO/PALAVRA designa o Filho, JESUS CRISTO; manter distinção Pai/Filho e não reduzir encarnação a mensagem escrita.)\n(CENA 1: ANTES DA CRIAÇÃO)\nNO PRINCÍPIO / VERBO JÁ EXISTIR.\nVERBO COM DEUS / VERBO SER DEUS.\nVERBO / DESDE PRINCÍPIO COM DEUS.\nTUDO CRIADO POR MEIO DELE / SEM ELE NADA CRIADO.\nNELE VIDA / VIDA LUZ PARA HUMANIDADE.\nLUZ BRILHAR NA ESCURIDÃO / TREVAS NÃO ACOLHER.\n(CENA 2: JOÃO BATISTA — TESTEMUNHA, NÃO A LUZ)\nDEUS ENVIAR HOMEM CHAMADO JOÃO.\nJOÃO VIR PARA TESTEMUNHAR SOBRE LUZ / PESSOAS CRER POR TESTEMUNHO.\nJOÃO NÃO SER LUZ / APENAS TESTEMUNHA.\n(CENA 3: VERBO VEM AO MUNDO)\nVERBO LUZ VERDADEIRA / VIR AO MUNDO / ILUMINAR PESSOAS.\nMUNDO CRIADO POR ELE / MAS MUNDO NÃO RECONHECER.\nELE VIR AOS SEUS / MUITOS NÃO RECEBER.\nQUEM RECEBER E CRER NO NOME DELE / DEUS DAR PODER TORNAR-SE FILHO DE DEUS.\nISSO NÃO DEPENDER NASCIMENTO HUMANO / ORIGEM EM DEUS.\n(CENA 4: ENCARNAÇÃO)\nVERBO SE FAZER CARNE / TORNAR-SE HUMANO / VIVER ENTRE NÓS.\nNÓS VER GLÓRIA DELE / GLÓRIA FILHO ÚNICO DO PAI / CHEIO GRAÇA E VERDADE.\n(CENA 5: TESTEMUNHO E REVELAÇÃO)\nJOÃO TESTEMUNHAR: ELE VIR DEPOIS DE MIM / MAS EXISTIR ANTES DE MIM.\nDA PLENITUDE DELE / NÓS RECEBER GRAÇA SOBRE GRAÇA.\nDEUS DAR LEI POR MOISÉS / GRAÇA E VERDADE VIR POR JESUS CRISTO.\nNENHUMA PESSOA VER DEUS EM SUA PLENITUDE / FILHO UNIGÊNITO JUNTO PAI / ELE REVELAR QUEM É DEUS.\n(ENCERRAMENTO — PALAVRA DA SALVAÇÃO.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Vigília|primeira-leitura|Is 62,1-5": "(ROTEIRO EDITORIAL — PROFETA FALA DE SIÃO/JERUSALÉM; COMPARA A ALIANÇA A UM CASAMENTO)\nPOR AMOR SIÃO / EU NÃO CALAR / POR JERUSALÉM NÃO DESCANSAR.\nATÉ JUSTIÇA DE JERUSALÉM NASCER COMO LUZ AMANHECER / SALVAÇÃO BRILHAR COMO TOCHA.\nPOVOS TODOS VER JUSTIÇA / REIS TERRA VER GLÓRIA.\nDEUS DAR A JERUSALÉM UM NOME NOVO.\nJERUSALÉM / COMO COROA BELA NAS MÃOS DO SENHOR / COMO DIADEMA NAS MÃOS DE DEUS.\nANTES NOME DELA 'ABANDONADA' / SUA TERRA 'DESERTA'.\nAGORA DEUS CHAMAR 'PREDILETA' / SUA TERRA 'DESPOSADA'.\nPOR QUÊ? SENHOR ALEGRAR-SE NELA / SUA TERRA TER COMO ESPOSO.\nCOMO JOVEM CASAR MULHER / ASSIM TEU CONSTRUTOR SE UNIR A TI.\nCOMO ESPOSO ALEGRAR COM ESPOSA / ASSIM DEUS ALEGRAR CONTIGO.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Vigília|segunda-leitura|At 13,16-17.22-25": "(ROTEIRO EDITORIAL — PAULO NA SINAGOGA DE ANTIOQUIA DA PISÍDIA)\nPAULO LEVANTAR / FAZER SINAL COM MÃO / FALAR AOS ISRAELITAS E QUEM RESPEITA DEUS: ESCUTEM.\nDEUS ESCOLHER NOSSOS ANTEPASSADOS / FAZER POVO CRESCER NO EGITO ONDE MORAVAM COMO ESTRANGEIROS.\nCOM BRAÇO PODEROSO / DEUS LIBERTAR POVO DO EGITO.\nDEUS ESCOLHER DAVID COMO REI.\nDEUS TESTEMUNHAR: ENCONTREI DAVID FILHO JESSÉ / HOMEM SEGUNDO MEU CORAÇÃO / ELE FARÁ MINHA VONTADE.\nDA DESCENDÊNCIA DAVID / CONFORME PROMESSA / DEUS FAZER NASCER JESUS / SALVADOR ISRAEL.\nANTES JESUS CHEGAR / JOÃO PROCLAMAR BATISMO DE CONVERSÃO A ISRAEL.\nJOÃO PERTO FINAL MISSÃO / DIZER: EU NÃO SOU AQUELE QUE VOCÊS PENSAM.\nDEPOIS DE MIM / VIR ALGUÉM / EU NEM DIGNO DESAMARRAR SANDÁLIA DELE.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Noite|primeira-leitura|Is 9,1-6": "(ROTEIRO EDITORIAL — VISÃO PROFÉTICA DE LUZ, LIBERTAÇÃO E CRIANÇA QUE REINARÁ)\nPOVO VIVER NA ESCURIDÃO / AGORA VER LUZ GRANDE.\nPESSOAS VIVER SOMBRA MORTE / LUZ BRILHAR SOBRE ELAS.\nDEUS AUMENTAR ALEGRIA / POVO CELEBRAR COMO NA COLHEITA / COMO NA VITÓRIA.\nDEUS QUEBRAR JUGO OPRESSÃO / PESO NOS OMBROS / BASTÃO DO OPRESSOR / COMO ANTIGA VITÓRIA EM MADIÃ.\nBOTAS GUERRA E ROUPAS MANCHADAS SANGUE / SERÃO QUEIMADAS / GUERRA TERMINAR.\nPOR QUÊ? MENINO NASCER PARA NÓS / FILHO SER DADO.\nPODER REAL SOBRE SEUS OMBROS.\nTÍTULOS: CONSELHEIRO ADMIRÁVEL / DEUS FORTE / PAI ETERNO / PRÍNCIPE DA PAZ.\nSEU GOVERNO / PAZ NÃO TER FIM.\nTRONO E REINO DAVID / JUSTIÇA E DIREITO FIRMAR / AGORA E PARA SEMPRE.\nSENHOR DO UNIVERSO / REALIZAR ISSO.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Noite|segunda-leitura|Tt 2,11-14": "(ROTEIRO EDITORIAL — ENSINAMENTO A TITO)\nGRAÇA DE DEUS APARECER / OFERECER SALVAÇÃO PARA TODAS PESSOAS.\nESSA GRAÇA ENSINAR NÓS RENUNCIAR IMPIEDADE E DESEJOS DO MUNDO.\nAGORA / NESTE TEMPO / VIVER COM TEMPERANÇA / JUSTIÇA / DEVOÇÃO A DEUS.\nESPERAR FELIZ ESPERANÇA / GLÓRIA NOSSO GRANDE DEUS E SALVADOR JESUS CRISTO MANIFESTAR-SE.\nJESUS CRISTO / ENTREGAR A SI MESMO POR NÓS.\nPARA NOS LIBERTAR DE TODO PECADO / PURIFICAR POVO PARA ELE.\nPOVO DELE / DESEJAR PRATICAR BOAS OBRAS.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Noite|evangelho|Lc 2,1-14": "(ROTEIRO EDITORIAL — NARRADOR, JOSÉ, MARIA, PASTORES, ANJO E CORO CELESTE)\n(CENA 1: DECRETO E VIAGEM)\nCÉSAR AUGUSTO / ORDENAR RECENSEAMENTO NO IMPÉRIO.\nPRIMEIRO RECENSEAMENTO / QUIRINO GOVERNAR SÍRIA.\nTODOS IR CIDADE DE ORIGEM / REGISTRAR.\nJOSÉ SAIR NAZARÉ GALILEIA / IR BELÉM CIDADE DE DAVID NA JUDEIA.\nJOSÉ DESCENDENTE DAVID / IR COM MARIA ESPOSA / GRÁVIDA.\n(CENA 2: NASCIMENTO)\nEM BELÉM / HORA PARTO CHEGAR / MARIA DAR À LUZ FILHO PRIMOGÊNITO.\nENVOLVER MENINO EM PANOS / DEITAR MANJEDOURA.\nPOR QUÊ? NÃO TER LUGAR HOSPEDARIA.\n(CENA 3: PASTORES NO CAMPO)\nNA REGIÃO / PASTORES CUIDAR REBANHOS DURANTE NOITE.\nANJO DO SENHOR APARECER / GLÓRIA DE DEUS BRILHAR / PASTORES FICAR COM MEDO.\nANJO: NÃO TENHAM MEDO / TRAGO BOA NOTÍCIA / ALEGRIA GRANDE PARA TODO POVO.\nHOJE NA CIDADE DAVID / NASCER SALVADOR / ELE CRISTO SENHOR.\nSINAL: BEBÊ ENVOLTO PANOS / DEITADO MANJEDOURA.\n(CENA 4: ANJOS LOUVAM)\nMULTIDÃO EXÉRCITO CELESTE APARECER COM ANJO / LOUVAR:\nGLÓRIA A DEUS NAS ALTURAS / PAZ NA TERRA ÀS PESSOAS POR DEUS AMADAS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Aurora|primeira-leitura|Is 62,11-12": "(ROTEIRO EDITORIAL — ANÚNCIO A SIÃO)\nSENHOR ANUNCIAR ATÉ CONFINS TERRA:\nDIZER A SIÃO / VEJAM / SEU SALVADOR ESTÁ VINDO.\nCOM ELE / RECOMPENSA / PRÊMIO QUE ELE TRAZ.\nPOVO DELE / CHAMADO POVO SANTO / RESGATADOS DO SENHOR.\nCIDADE / CHAMADA PROCURADA / NÃO MAIS ABANDONADA.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Aurora|segunda-leitura|Tt 3,4-7": "(ROTEIRO EDITORIAL — PAULO EXPLICA A SALVAÇÃO COMO DOM)\nDEUS NOSSO SALVADOR / MOSTRAR BONDADE E AMOR À HUMANIDADE.\nELE NOS SALVAR / NÃO POR MERECIMENTO DE NOSSAS OBRAS JUSTAS.\nPOR SUA MISERICÓRDIA / ELE SALVAR.\nPELO BANHO DE REGENERAÇÃO / NASCER DE NOVO / ESPÍRITO SANTO RENOVAR NÓS.\nDEUS DERRAMAR ESPÍRITO SANTO ABUNDANTEMENTE / POR JESUS CRISTO NOSSO SALVADOR.\nASSIM / POR SUA GRAÇA / SER JUSTIFICADOS.\nNÓS NOS TORNAR HERDEIROS / ESPERANÇA VIDA ETERNA.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Aurora|evangelho|Lc 2,15-20": "(ROTEIRO EDITORIAL — NARRADOR, PASTORES, MARIA, JOSÉ, MENINO)\n(CENA 1: ANJOS PARTEM)\nANJOS SUBIR CÉU / PASTORES FALAR UNS AOS OUTROS:\nVAMOS BELÉM / VER ACONTECIMENTO QUE SENHOR NOS ANUNCIOU.\n(CENA 2: ENCONTRO EM BELÉM)\nPASTORES IR DEPRESSA / ENCONTRAR MARIA / JOSÉ / MENINO NA MANJEDOURA.\nPASTORES VER MENINO / CONTAR A TODOS MENSAGEM QUE ANJO ANUNCIAR.\nPESSOAS OUVIR / FICAR ADMIRADAS.\n(CENA 3: MARIA E TESTEMUNHO)\nMARIA GUARDAR TODAS ESSAS PALAVRAS / REFLETIR NO CORAÇÃO.\nPASTORES RETORNAR / LOUVAR E GLORIFICAR DEUS.\nTUDO QUE VIRAM E OUVIRAM / ACONTECEU CONFORME ANÚNCIO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Dia|primeira-leitura|Is 52,7-10": "(ROTEIRO EDITORIAL — MENSAGEIRO, SENTINELAS E JERUSALÉM)\n(IMAGEM: MONTANHAS / MENSAGEIRO QUE CAMINHA)\nMENSAGEIRO CAMINHAR SOBRE MONTANHAS / TRAZER BOA NOTÍCIA PAZ E SALVAÇÃO.\nELE ANUNCIAR A SIÃO: SEU DEUS REINA!\n(CENA: SENTINELAS)\nGUARDAS DA CIDADE / LEVANTAR VOZ / JUNTOS ALEGRAR.\nCOM PRÓPRIOS OLHOS / VER SENHOR VOLTAR A SIÃO.\n(CENA: JERUSALÉM É RESTAURADA)\nRUÍNAS JERUSALÉM / COMO SE PUDESSEM CANTAR ALEGRIA.\nSENHOR CONSOLAR SEU POVO / RESGATAR JERUSALÉM.\nDEUS REVELAR PODER DE SEU BRAÇO SANTO DIANTE TODAS NAÇÕES.\nATÉ CONFINS TERRA / POVOS VER SALVAÇÃO DO NOSSO DEUS.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Natal — Dia|segunda-leitura|Hb 1,1-6": "(ROTEIRO EDITORIAL — CRISTO FILHO DE DEUS / DISTINTO DE ANJOS)\nANTIGAMENTE / DEUS FALAR MUITAS VEZES E DE DIFERENTES MANEIRAS AOS ANTEPASSADOS / POR MEIO PROFETAS.\nAGORA / NESTES ÚLTIMOS TEMPOS / DEUS FALAR POR SEU FILHO.\nFILHO / DEUS CONSTITUIR HERDEIRO DE TUDO / POR ELE CRIOU UNIVERSO.\nFILHO / BRILHO DA GLÓRIA DE DEUS / IMAGEM PERFEITA DO SER DE DEUS.\nELE SUSTENTAR TUDO POR SUA PALAVRA PODEROSA.\nELE REALIZAR PURIFICAÇÃO DOS PECADOS / SENTAR À DIREITA DE DEUS NO CÉU.\nELE MAIOR QUE ANJOS / RECEBER NOME MAIS ELEVADO.\nDEUS NÃO DIZER A NENHUM ANJO: VOCÊ MEU FILHO / HOJE EU TE GEREI.\nDEUS DIZER DO FILHO: EU SER PARA ELE PAI / ELE PARA MIM FILHO.\nQUANDO DEUS INTRODUZIR SEU PRIMOGÊNITO NO MUNDO / ANJOS DE DEUS ADORAR ELE.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Sagrada Família|primeira-leitura|Gn 15,1-6; 21,1-3": "(ROTEIRO EDITORIAL — DUAS ÉPOCAS: PROMESSA A ABRÃO E NASCIMENTO ISAAC)\n(CENA 1: VISÃO A ABRÃO)\nDEUS APARECER A ABRÃO EM VISÃO / DIZER:\nNÃO TER MEDO / EU TEU ESCUDO / TUA RECOMPENSA GRANDE.\nABRÃO: SENHOR / EU SEM FILHO / QUANDO MORRER / MEU HERDEIRO SERVO ELIEZER DAMASCO.\nDEUS: NÃO SER ELE SEU HERDEIRO / HERDEIRO SERÁ FILHO NASCIDO DE VOCÊ.\n(CENA 2: PROMESSA DAS ESTRELAS)\nDEUS LEVAR ABRÃO FORA CASA / MOSTRAR CÉU / DIZER CONTAR ESTRELAS SE CONSEGUIR.\nASSIM SUA DESCENDÊNCIA SERÁ NUMEROSA.\nABRÃO ACREDITAR NO SENHOR / DEUS CONSIDERAR SUA FÉ COMO JUSTIÇA.\n(CENA 3: CUMPRIMENTO DA PROMESSA)\nTEMPO PASSAR / DEUS VISITAR SARA / CUMPRIR O QUE PROMETEU.\nSARA CONCEBER / DAR FILHO A ABRAÃO JÁ IDOSOS / NO TEMPO QUE DEUS MARCOU.\nABRAÃO DAR AO FILHO NOME ISAAC.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Sagrada Família|segunda-leitura|Hb 11,8.11-12.17-19": "(ROTEIRO EDITORIAL — FÉ DE ABRAÃO E SARA / PASSAGEM DE GERAÇÕES)\nABRAÃO OUVIR DEUS CHAMAR / PELA FÉ OBEDECER.\nPARTIR PARA TERRA QUE RECEBERIA COMO HERANÇA / NÃO SABER CAMINHO.\nSARA / MESMO DEPOIS IDADE NORMAL TER FILHOS / PELA FÉ / DEUS CONCEDER SER MÃE.\nELA CONFIAR NA FIDELIDADE DAQUELE QUE PROMETEU.\nDE UM HOMEM MUITO IDOSO / DESCENDÊNCIA NASCER NUMEROSA / COMO ESTRELAS CÉU E AREIA PRAIA.\n(CENA: ABRAÃO É PROVADO)\nDEUS COLOCAR ABRAÃO À PROVA / ABRAÃO DISPOSTO OFERECER FILHO ISAAC.\nISAAC / FILHO POR QUEM DEUS PROMETEU DESCENDÊNCIA.\nABRAÃO CONFIAR QUE DEUS PODE ATÉ RESSUSCITAR MORTOS.\nPOR ISSO / FIGURADAMENTE / RECEBER ISAAC DE VOLTA.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Santa Maria, Mãe de Deus|primeira-leitura|Nm 6,22-27": "(ROTEIRO EDITORIAL — DEUS, MOISÉS, AARÃO E SEUS FILHOS / BÊNÇÃO A ISRAEL)\nDEUS FALAR MOISÉS: DIGA A AARÃO E FILHOS COMO ABENÇOAR POVO ISRAEL.\n(ORAÇÃO DE BÊNÇÃO)\nSENHOR / TE ABENÇOAR E PROTEGER.\nSENHOR / FAZER LUZ DE SUA FACE BRILHAR SOBRE VOCÊ / SER FAVORÁVEL A VOCÊ.\nSENHOR / OLHAR PARA VOCÊ / DAR PAZ.\nDEUS: ASSIM ELES INVOCAR MEU NOME SOBRE ISRAEL / EU ABENÇOAR POVO.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Santa Maria, Mãe de Deus|segunda-leitura|Gl 4,4-7": "(ROTEIRO EDITORIAL — PLENITUDE DO TEMPO / FILIAÇÃO DIVINA)\nQUANDO TEMPO CERTO CHEGAR / DEUS ENVIAR SEU FILHO.\nFILHO NASCER DE MULHER / NASCER SOB LEI.\nPARA LIBERTAR QUEM ESTAVA SOB LEI / NÓS TORNAR FILHOS ADOTIVOS DE DEUS.\nVOCÊS AGORA FILHOS DE DEUS.\nDEUS ENVIAR ESPÍRITO DE SEU FILHO AOS NOSSOS CORAÇÕES.\nESSE ESPÍRITO CLAMAR: ABBA / PAI!\nPOR ISSO / VOCÊ NÃO SER MAIS ESCRAVO / MAS FILHO.\nSE FILHO / TAMBÉM HERDEIRO / POR GRAÇA DE DEUS.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Santa Maria, Mãe de Deus|evangelho|Lc 2,16-21": "(ROTEIRO EDITORIAL — PASTORES, MARIA, JOSÉ E MENINO JESUS)\nPASTORES IR DEPRESSA PARA BELÉM.\nENCONTRAR MARIA / JOSÉ / MENINO DEITADO MANJEDOURA.\nPASTORES VER MENINO / CONTAR ANÚNCIO QUE RECEBERAM SOBRE ELE.\nPESSOAS OUVIR / FICAR ADMIRADAS.\nMARIA GUARDAR ESSAS PALAVRAS / REFLETIR EM SEU CORAÇÃO.\nPASTORES VOLTAR / DAR GLÓRIA E LOUVAR A DEUS.\nPOR QUÊ? TUDO QUE VIRAM E OUVIRAM / IGUAL AO QUE FOI ANUNCIADO.\nOITO DIAS PASSAR / MENINO SER CIRCUNCIDADO.\nDAR-LHE NOME JESUS / NOME QUE ANJO ANUNCIARA ANTES DA CONCEPÇÃO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Epifania do Senhor|primeira-leitura|Is 60,1-6": "(ROTEIRO EDITORIAL — PROFETA FALA A JERUSALÉM / NAÇÕES CHEGAM)\nJERUSALÉM / LEVANTAR / BRILHAR / SUA LUZ CHEGAR.\nGLÓRIA SENHOR BRILHAR SOBRE VOCÊ.\nTREVAS COBRIR TERRA / ESCURIDÃO POVOS.\nMAS SOBRE JERUSALÉM / SENHOR SURGIR / GLÓRIA ILUMINAR.\nNAÇÕES CAMINHAR EM DIREÇÃO À SUA LUZ / REIS PARA CLARIDADE DA AURORA.\n(CENA: REUNIÃO DOS FILHOS E FILHAS)\nOLHE AO REDOR / PESSOAS SE REUNIR / VIR ENCONTRAR VOCÊ.\nSEUS FILHOS CHEGAR DE LONGE / SUAS FILHAS TRAZIDAS NOS BRAÇOS.\nVOCÊ VER / CORAÇÃO BATER DE ALEGRIA / FICAR RADIANTE.\nRIQUEZAS DAS NAÇÕES / VIR ATÉ JERUSALÉM.\nMULTIDÕES CAMELOS / MADIÃ E EFÁ / POVOS SABÁ.\nELES TRAZER OURO E INCENSO / PROCLAMAR GLÓRIA SENHOR.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Epifania do Senhor|segunda-leitura|Ef 3,2-3.5-6": "(ROTEIRO EDITORIAL — REVELAÇÃO DE CRISTO / UNIÃO DE JUDEUS E NÃO JUDEUS)\nPAULO → IRMÃOS: VOCÊS OUVIR SOBRE MISSÃO QUE DEUS ME CONFIAR POR GRAÇA / PARA AJUDAR VOCÊS.\nDEUS REVELAR A MIM O MISTÉRIO DE CRISTO.\nGERAÇÕES PASSADAS / PESSOAS NÃO CONHECER ESSE MISTÉRIO COMO AGORA.\nESPÍRITO SANTO REVELAR A APÓSTOLOS E PROFETAS.\nMISTÉRIO: POVOS NÃO JUDEUS / COM POVO JUDEU / RECEBER MESMA HERANÇA.\nTODOS PERTENCER AO MESMO CORPO.\nTODOS PARTICIPAR DA MESMA PROMESSA EM JESUS CRISTO / POR MEIO EVANGELHO.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|CICLO DO NATAL — CELEBRAÇÕES DE REPERTÓRIO|Epifania do Senhor|evangelho|Mt 2,1-12": "(ROTEIRO EDITORIAL — MAGOS DO ORIENTE, REI HERODES, SACERDOTES, MARIA E MENINO)\n(CENA 1: MAGOS CHEGAM)\nJESUS NASCER BELÉM JUDEIA / TEMPO REI HERODES.\nMAGOS ORIENTE CHEGAR JERUSALÉM / PERGUNTAR:\nONDE NASCEU REI DOS JUDEUS? / NÓS VIMOS ESTRELA ORIENTE / VIMOS ADORAR.\nHERODES FICAR PERTURBADO / PESSOAS DE JERUSALÉM TAMBÉM.\n(CENA 2: CONSULTA À ESCRITURA)\nHERODES CHAMAR SACERDOTES E ESCRIBAS / PERGUNTAR ONDE MESSIAS NASCERÁ.\nELES RESPONDER: BELÉM JUDEIA / PROFETA DIZER DELA VIRÁ CHEFE / PASTOR DE ISRAEL.\n(CENA 3: HERODES ENVIA OS MAGOS)\nHERODES CHAMAR MAGOS EM SEGREDO / PERGUNTAR QUANDO ESTRELA APARECEU.\nHERODES ENVIAR BELÉM: PROCUREM MENINO / QUANDO ENCONTRAR / AVISEM / EU TAMBÉM QUERO ADORÁ-LO.\n(CENA 4: MAGOS SEGUEM A ESTRELA)\nMAGOS PARTIR / ESTRELA QUE VIRAM ORIENTE / IR À FRENTE / PARAR SOBRE LUGAR MENINO.\nAO VER ESTRELA / FICAR MUITO ALEGRES.\nMAGOS ENTRAR CASA / ENCONTRAR MENINO COM SUA MÃE MARIA.\nPROSTRAR-SE / ADORAR MENINO.\nABRIR TESOUROS / OFERECER OURO / INCENSO / MIRRA.\n(CENA 5: RETORNO)\nSONHO AVISAR MAGOS / NÃO VOLTAR HERODES.\nMAGOS REGRESSAR SUA TERRA POR OUTRO CAMINHO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|2º Domingo|evangelho|Jo 1,35-42": "(ROTEIRO EDITORIAL — JOÃO BATISTA, DOIS DISCÍPULOS, JESUS, ANDRÉ E SIMÃO)\nJOÃO BATISTA COM DOIS DISCÍPULOS / VER JESUS PASSAR.\nJOÃO: VEJAM / CORDEIRO DE DEUS.\nDOIS OUVIR / COMEÇAR SEGUIR JESUS.\nJESUS VIRAR / PERGUNTAR: O QUE VOCÊS PROCURAM?\nDISCÍPULOS: RABI / SIGNIFICA MESTRE / ONDE VOCÊ MORA?\nJESUS: VENHAM VER.\nELES IR / VER ONDE JESUS MORAR / PERMANECER COM ELE NAQUELE DIA.\nHORA APROXIMADA / QUATRO TARDE.\nANDRÉ / IRMÃO SIMÃO PEDRO / UM DOS QUE OUVIU JOÃO.\nANDRÉ ENCONTRAR SIMÃO: NÓS ENCONTRAMOS MESSIAS / SIGNIFICA CRISTO.\nANDRÉ LEVAR SIMÃO A JESUS.\nJESUS OLHAR SIMÃO: VOCÊ SIMÃO / FILHO DE JOÃO / AGORA CHAMAR CEFAS / SIGNIFICA PEDRO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|3º Domingo|evangelho|Mc 1,14-20": "(ROTEIRO EDITORIAL — MOVIMENTO DA GALILEIA À BEIRA DO LAGO)\nJOÃO BATISTA SER PRESO / JESUS IR GALILEIA / ANUNCIAR EVANGELHO DE DEUS.\nJESUS: TEMPO SE CUMPRIU / REINO DE DEUS PERTO / CONVERTER-SE / ACREDITAR NO EVANGELHO.\n(CENA: MARGEM MAR GALILEIA)\nJESUS VER SIMÃO E IRMÃO ANDRÉ / PESCADORES / LANÇAR REDES AO MAR.\nJESUS: VENHAM COMIGO / EU FAREI VOCÊS PESCADORES DE PESSOAS.\nSIMÃO E ANDRÉ / IMEDIATAMENTE DEIXAR REDES / SEGUIR JESUS.\nJESUS CAMINHAR MAIS ADIANTE / VER TIAGO FILHO ZEBEDEU E IRMÃO JOÃO.\nELES NO BARCO / CONSERTAR REDES.\nJESUS CHAMAR / ELES DEIXAR PAI ZEBEDEU NO BARCO COM TRABALHADORES / SEGUIR JESUS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|4º Domingo|evangelho|Mc 1,21-28": "(ROTEIRO EDITORIAL — SINAGOGA DE CAFARNAUM, JESUS, HOMEM E MULTIDÃO)\nJESUS CHEGAR CAFARNAUM.\nSÁBADO / JESUS ENTRAR SINAGOGA / ENSINAR.\nPESSOAS ADMIRAR / JESUS ENSINAR COM AUTORIDADE / DIFERENTE DOS ESCRIBAS.\nNA SINAGOGA HOMEM COM ESPÍRITO IMPURO / COMEÇAR GRITAR:\nJESUS DE NAZARÉ / O QUE VOCÊ QUER CONOSCO?\nVOCÊ VEIO NOS DESTRUIR? / EU SEI QUEM VOCÊ / SANTO DE DEUS.\nJESUS REPREENDER ESPÍRITO: CALAR / SAIR DESSE HOMEM!\nESPÍRITO IMPURO AGITAR HOMEM VIOLENTAMENTE / GRITAR / SAIR.\nTODOS ASSUSTADOS E ADMIRADOS / PERGUNTAR:\nQUE ENSINAMENTO NOVO É ESSE? / AUTORIDADE TÃO GRANDE.\nATÉ ESPÍRITOS IMPUROS / ELE ORDENAR / ELES OBEDECER.\nNOTÍCIA SOBRE JESUS / ESPALHAR POR TODA GALILEIA.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|5º Domingo|evangelho|Mc 1,29-39": "(ROTEIRO EDITORIAL — QUATRO CENÁRIOS: SINAGOGA, CASA, PORTA E LUGAR DESERTO)\nJESUS SAIR SINAGOGA / COM TIAGO E JOÃO / IR CASA SIMÃO E ANDRÉ.\nSOGRA SIMÃO / DE CAMA COM FEBRE / PESSOAS CONTAR JESUS.\nJESUS APROXIMAR / SEGURAR MÃO / AJUDAR LEVANTAR.\nFEBRE DESAPARECER / ELA COMEÇAR SERVIR.\n(CENA: APÓS PÔR DO SOL)\nPESSOAS TRAZER MUITOS DOENTES E POSSESSOS.\nCIDADE INTEIRA REUNIR JUNTO PORTA.\nJESUS CURAR MUITAS DOENÇAS / EXPULSAR ESPÍRITOS IMPUROS.\nJESUS NÃO PERMITIR ESPÍRITOS FALAR / ELES SABER QUEM JESUS ERA.\n(CENA: MANHÃ CEDO)\nJESUS ACORDAR AINDA ESCURO / IR LUGAR DESERTO / ORAR.\nSIMÃO E COMPANHEIROS PROCURAR / ENCONTRAR.\nELES: TODOS PROCURAM VOCÊ.\nJESUS: VAMOS OUTRAS ALDEIAS / PRECISO TAMBÉM ANUNCIAR EVANGELHO / PARA ISSO EU VIM.\nJESUS PERCORRER GALILEIA / ENSINAR SINAGOGAS / EXPULSAR ESPÍRITOS IMPUROS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|6º Domingo|evangelho|Mc 1,40-45": "(ROTEIRO EDITORIAL — HOMEM COM LEPRA E JESUS; MANTER FALA DE CADA UM)\nHOMEM COM LEPRA / APROXIMAR JESUS / AJOELHAR / SUPLICAR:\nSE VOCÊ QUISER / PODE ME PURIFICAR.\nJESUS SENTIR COMPAIXÃO / ESTENDER MÃO / TOCAR HOMEM.\nJESUS: EU QUERO / FIQUE LIMPO.\nIMEDIATAMENTE LEPRA DESAPARECER / HOMEM FICAR CURADO.\nJESUS DAR ORDEM FIRME:\nNÃO CONTAR A NINGUÉM / IR MOSTRAR-SE SACERDOTE.\nOFERECER PELA PURIFICAÇÃO O QUE MOISÉS DETERMINOU / SERVIR COMO TESTEMUNHO.\nHOMEM SAIR / EM VEZ DE SILÊNCIO / ESPALHAR NOTÍCIA.\nCONSEQUÊNCIA / JESUS NÃO PODER ENTRAR PUBLICAMENTE CIDADES.\nJESUS PERMANECER EM LUGARES AFASTADOS / PESSOAS IR ENCONTRÁ-LO DE TODOS LADOS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|7º Domingo|evangelho|Mc 2,1-12": "(ROTEIRO EDITORIAL — CASA CHEIA, QUATRO CARREGADORES, HOMEM PARALISADO, ESCRIBAS, JESUS)\nJESUS VOLTAR CAFARNAUM / NOTÍCIA JESUS EM CASA / MUITAS PESSOAS REUNIR.\nNEM ESPAÇO JUNTO PORTA / JESUS ENSINAR PALAVRA.\nQUATRO HOMENS TRAZER HOMEM PARALISADO NUM LEITO.\nMULTIDÃO BLOQUEAR ENTRADA / ELES SUBIR TELHADO / ABRIR TETO SOBRE JESUS.\nDESCER LEITO COM HOMEM DIANTE JESUS.\nJESUS VER FÉ DELES / DIZER AO HOMEM:\nFILHO / SEUS PECADOS ESTÃO PERDOADOS.\nESCRIBAS SENTADOS / PENSAR EM SILÊNCIO:\nPOR QUE JESUS FALAR ASSIM? / ISSO BLASFÊMIA / SÓ DEUS PODER PERDOAR PECADOS.\nJESUS PERCEBER PENSAMENTOS / PERGUNTAR:\nPOR QUE PENSAM ASSIM?\nQUAL MAIS FÁCIL DIZER? PECADOS PERDOADOS OU LEVANTAR E ANDAR?\nPARA VOCÊS SABEREM / FILHO DO HOMEM TEM PODER NA TERRA PARA PERDOAR PECADOS.\nJESUS → HOMEM: EU ORDENO / LEVANTAR / PEGAR LEITO / IR PARA CASA.\nHOMEM LEVANTAR / PEGAR LEITO / SAIR DIANTE TODOS.\nPESSOAS ADMIRADAS / LOUVAR DEUS: NUNCA VIMOS ALGO ASSIM.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|8º Domingo|evangelho|Mc 2,18-22": "(ROTEIRO EDITORIAL — DISCUSSÃO SOBRE JEJUM E TRÊS IMAGENS)\nDISCÍPULOS JOÃO BATISTA E FARISEUS JEJUAR.\nPESSOAS PERGUNTAR JESUS:\nPOR QUE ELES JEJUAR / MAS SEUS DISCÍPULOS NÃO JEJUAR?\nJESUS: CONVIDADOS DE CASAMENTO / ENQUANTO NOIVO COM ELES / VÃO JEJUAR?\nENQUANTO NOIVO ESTÁ PRESENTE / NÃO.\nDIAS VIRÃO / NOIVO SERÁ TIRADO / ENTÃO ELES JEJUAR.\n(IMAGEM 1: PANO)\nNINGUÉM COLOCAR REMENDO PANO NOVO EM ROUPA VELHA.\nPANO NOVO PUXAR VELHO / RASGO FICAR MAIOR.\n(IMAGEM 2: VINHO)\nNINGUÉM COLOCAR VINHO NOVO EM ODRES VELHOS.\nVINHO NOVO ROMPER ODRES / PERDER VINHO E RECIPIENTES.\nVINHO NOVO / ODRES NOVOS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|9º Domingo|evangelho|Mc 2,23–3,6": "(ROTEIRO EDITORIAL — FORMA LONGA IMPORTADA; DUAS CENAS SOBRE SÁBADO)\n(CENA 1: CAMPO DE TRIGO)\nSÁBADO / JESUS ATRAVESSAR CAMPOS / DISCÍPULOS COLHER ESPIGAS.\nFARISEUS: VEJA / ELES FAZER SÁBADO O QUE NÃO É PERMITIDO.\nJESUS: VOCÊS NÃO LER O QUE DAVID FEZ QUANDO ELE E COMPANHEIROS TINHAM FOME?\nDAVID ENTRAR CASA DE DEUS / TEMPO SUMO SACERDOTE ABIATAR / COMER PÃES CONSAGRADOS.\nSOMENTE SACERDOTES PODIAM COMER / MAS DAVID DAR TAMBÉM A COMPANHEIROS.\nJESUS: SÁBADO FEITO PARA BENEFÍCIO HUMANO / NÃO HUMANO PARA SÁBADO.\nFILHO DO HOMEM / SENHOR TAMBÉM DO SÁBADO.\n(CENA 2: SINAGOGA)\nJESUS ENTRAR SINAGOGA / HOMEM COM MÃO ATROFIADA ESTAR ALI.\nFARISEUS OBSERVAR / QUERER ACUSAR JESUS CASO CURASSE NO SÁBADO.\nJESUS → HOMEM: LEVANTAR / VIR AO CENTRO.\nJESUS → LÍDERES: NO SÁBADO / FAZER BEM OU MAL? SALVAR VIDA OU MATAR?\nLÍDERES FICAR CALADOS.\nJESUS OLHAR COM INDIGNAÇÃO / TRISTE CORAÇÃO DELES ENDURECIDO.\nJESUS → HOMEM: ESTENDER MÃO.\nHOMEM ESTENDER / MÃO CURADA.\nFARISEUS SAIR / REUNIR COM HERODIANOS / PLANEJAR MATAR JESUS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|10º Domingo|evangelho|Mc 3,20-35": "(ROTEIRO EDITORIAL — DISTINGUIR PARENTES, ESCRIBAS, JESUS E MULTIDÃO)\n(CENA 1: MULTIDÃO NA CASA)\nJESUS ENTRAR CASA COM DISCÍPULOS / PESSOAS REUNIR TANTO / NEM CONSEGUIR COMER.\nPARENTES OUVIR / IR TENTAR DETÊ-LO / DIZER JESUS ESTAR FORA DE SI.\n(CENA 2: ACUSAÇÃO DOS ESCRIBAS)\nESCRIBAS VINDOS JERUSALÉM:\nJESUS POSSESSO POR BELZEBU / ELE EXPULSAR DEMÔNIOS COM PODER CHEFE DEMÔNIOS.\nJESUS CHAMAR ESCRIBAS / FALAR PARÁBOLAS:\nCOMO SATANÁS EXPULSAR SATANÁS?\nREINO DIVIDIDO CONTRA SI / NÃO PODE PERMANECER.\nCASA DIVIDIDA CONTRA SI / NÃO PODE CONTINUAR.\nSE SATANÁS LUTAR CONTRA SI / ELE NÃO SUBSISTIR.\n(IMAGEM: HOMEM FORTE)\nNÃO POSSÍVEL ENTRAR CASA HOMEM FORTE / ROUBAR BENS / SEM PRIMEIRO AMARRÁ-LO.\nJESUS: PECADOS E BLASFÊMIAS PODEM SER PERDOADOS.\nMAS BLASFEMAR CONTRA ESPÍRITO SANTO / PECADO GRAVÍSSIMO NÃO PERDOADO.\nNARRADOR: JESUS DIZER ISSO PORQUE ELES ACUSAVAM JESUS DE TER ESPÍRITO IMPURO.\n(CENA 3: FAMÍLIA)\nMÃE JESUS E SEUS IRMÃOS / FICAR FORA CASA / MANDAR CHAMÁ-LO.\nMULTIDÃO: SUA MÃE E IRMÃOS ESTÃO LÁ FORA / TE PROCURAR.\nJESUS: QUEM MINHA MÃE / MEUS IRMÃOS?\nJESUS OLHAR PESSOAS AO REDOR:\nQUEM FAZ VONTADE DE DEUS / ESSA PESSOA MEU IRMÃO / MINHA IRMÃ / MINHA MÃE.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|11º Domingo|evangelho|Mc 4,26-34": "(ROTEIRO EDITORIAL — DUAS PARÁBOLAS DO CRESCIMENTO)\nJESUS EXPLICAR MULTIDÃO:\nREINO DE DEUS COMO HOMEM QUE ESPALHAR SEMENTE NO SOLO.\nHOMEM DORMIR / ACORDAR / DIA E NOITE PASSAR.\nSEMENTE GERMINAR E CRESCER / HOMEM NÃO SABER COMO.\nTERRA PRODUZ POR SI / PRIMEIRO BROTO / DEPOIS ESPIGA / DEPOIS GRÃO MADURO.\nQUANDO TRIGO MADURO / CHEGAR MOMENTO COLHEITA / HOMEM USAR FOICE.\n(CENA 2: GRÃO DE MOSTARDA)\nJESUS: COM O QUE COMPARAR REINO DE DEUS?\nSEMENTE MOSTARDA / MUITO PEQUENA QUANDO SEMEADA.\nDEPOIS CRESCER / TORNAR UMA DAS MAIORES PLANTAS DA HORTA.\nRAMOS GRANDES / PÁSSAROS ENCONTRAR SOMBRA E ABRIGO.\nJESUS ANUNCIAR A PALAVRA COM MUITAS PARÁBOLAS / CONFORME PESSOAS PODIAM ENTENDER.\nÀ MULTIDÃO FALAR PARÁBOLAS / EM PARTICULAR EXPLICAR TUDO DISCÍPULOS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|12º Domingo|evangelho|Mc 4,35-41": "(ROTEIRO EDITORIAL — BARCO, OUTRAS EMBARCAÇÕES, TEMPESTADE, MEDO E FÉ)\nANOITECER / JESUS → DISCÍPULOS: VAMOS ATRAVESSAR PARA OUTRA MARGEM.\nDISCÍPULOS DEIXAR MULTIDÃO / LEVAR JESUS NO BARCO / OUTROS BARCOS ACOMPANHAR.\nVENTO FORTE / TEMPESTADE / ONDAS ALTAS / ÁGUA ENTRAR NO BARCO.\nJESUS NA PARTE TRASEIRA / DORMIR SOBRE ALMOFADA.\nDISCÍPULOS ACORDAR JESUS: MESTRE / VOCÊ NÃO SE IMPORTA QUE NÓS MORRAMOS?\nJESUS LEVANTAR / ORDENAR AO VENTO / DIZER AO MAR:\nCALAR / FICAR QUIETO!\nVENTO PARAR / MAR FICAR CALMO.\nJESUS → DISCÍPULOS: POR QUE VOCÊS TANTO MEDO? / AINDA NÃO TER FÉ?\nDISCÍPULOS FICAR MUITO ASSUSTADOS / PERGUNTAR UNS AOS OUTROS:\nQUEM É JESUS? / ATÉ VENTO E MAR OBEDECER A ELE!\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|13º Domingo|evangelho|Mc 5,21-43": "(ROTEIRO EDITORIAL — DUAS HISTÓRIAS ENTRELAÇADAS; JAIR0, FILHA, MULHER, JESUS, DISCÍPULOS; O TEXTO ORIGINAL IMPORTADO APENAS TEM FORMA LONGA)\n(CENA 1: JAÍRO PROCURA JESUS)\nJESUS ATRAVESSAR LAGO / MULTIDÃO REUNIR À BEIRA-MAR.\nJAÍRO / CHEFE SINAGOGA / CHEGAR / CAIR AOS PÉS JESUS / SUPLICAR:\nMINHA FILHA PERTO MORTE / VENHA / IMPONHA MÃOS PARA ELA VIVER.\nJESUS IR COM JAÍRO / MULTIDÃO GRANDE APERTAR JESUS.\n(CENA 2: MULHER COM HEMORRAGIA)\nMULHER SOFRER PERDA SANGUE HÁ DOZE ANOS.\nPROCURAR MÉDICOS / GASTAR DINHEIRO / NÃO MELHORAR / PIORAR.\nELA OUVIR SOBRE JESUS / APROXIMAR POR TRÁS ENTRE PESSOAS.\nELA PENSAR: SE EU TOCAR ROUPA DELE / FICAREI CURADA.\nMULHER TOCAR MANTO JESUS / HEMORRAGIA PARAR IMEDIATAMENTE / PERCEBER CURA.\nJESUS SENTIR FORÇA SAIR / VIRAR / PERGUNTAR: QUEM TOCOU MINHA ROUPA?\nDISCÍPULOS: MULTIDÃO APERTAR VOCÊ / COMO PERGUNTAR QUEM TOCOU?\nJESUS CONTINUAR PROCURAR QUEM TOCOU.\nMULHER COM MEDO / TREMENDO / CAIR DIANTE JESUS / CONTAR TODA VERDADE.\nJESUS: MINHA FILHA / SUA FÉ TE SALVOU.\n(CENA 3: NOTÍCIA DA MORTE)\nPESSOAS CASA JAÍRO CHEGAR: SUA FILHA MORREU / NÃO INCOMODAR MESTRE.\nJESUS → JAÍRO: NÃO TER MEDO / CONTINUAR ACREDITAR.\nJESUS LEVAR APENAS PEDRO, TIAGO, JOÃO.\n(CENA 4: CASA DE JAÍRO)\nPESSOAS CHORAR E GRITAR / JESUS PERGUNTAR POR QUÊ.\nJESUS: MENINA NÃO MORREU / DORME.\nPESSOAS RIR DE JESUS.\nJESUS MANDAR TODOS SAIR / FICAR PAIS DA MENINA E DISCÍPULOS.\nJESUS ENTRAR ONDE MENINA ESTÁ / PEGAR MÃO.\nJESUS: TALITHA KUM / MENINA EU TE ORDENO LEVANTAR!\nMENINA LEVANTAR IMEDIATAMENTE / COMEÇAR ANDAR / ELA TER DOZE ANOS.\nPESSOAS ADMIRADAS / JESUS PEDIR NÃO DIVULGAR / MANDAR DAR COMIDA À MENINA.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|14º Domingo|evangelho|Mc 6,1-6": "(ROTEIRO EDITORIAL — JESUS REJEITADO NA SUA TERRA)\nJESUS E DISCÍPULOS IR CIDADE DE ORIGEM DE JESUS.\nSÁBADO / JESUS ENSINAR SINAGOGA.\nMUITAS PESSOAS OUVIR / SURPRESAS:\nDE ONDE JESUS RECEBER SABEDORIA?\nCOMO ELE REALIZAR MILAGRES?\nELE NÃO É CARPINTEIRO / FILHO DE MARIA?\nNÃO CONHECEMOS TIAGO, JOSÉ, JUDAS, SIMÃO / IRMÃOS DELE? / E SUAS IRMÃS MORAM AQUI?\nPESSOAS FICAR ESCANDALIZADAS E DESCONFIAR.\nJESUS: PROFETA NÃO SER RESPEITADO NA PRÓPRIA TERRA / ENTRE PARENTES / NA PRÓPRIA CASA.\nNESSE LUGAR / JESUS NÃO FAZER GRANDES MILAGRES / APENAS IMPOR MÃOS SOBRE ALGUNS DOENTES E CURAR.\nJESUS ADMIRAR FALTA FÉ DELES.\nJESUS IR ALDEIAS VIZINHAS / CONTINUAR ENSINAR.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|15º Domingo|evangelho|Mc 6,7-13": "(ROTEIRO EDITORIAL — ENVIO DOS DOZE DOIS A DOIS)\nJESUS CHAMAR DOZE APÓSTOLOS / ENVIAR DOIS A DOIS.\nDAR AUTORIDADE SOBRE ESPÍRITOS IMPUROS.\nJESUS ORIENTAR VIAJAR SEM LEVAR PÃO / SACOLA / DINHEIRO.\nPODEM LEVAR BASTÃO / SANDÁLIAS / NÃO LEVAR DUAS TÚNICAS.\nJESUS: ENTRAR NUMA CASA / PERMANECER ALI ATÉ PARTIR DAQUELE LUGAR.\nSE ALDEIA NÃO RECEBER VOCÊS / PESSOAS NÃO ESCUTAR / SAIR / SACUDIR POEIRA DOS PÉS COMO TESTEMUNHO.\nAPÓSTOLOS SAIR / ANUNCIAR CONVERSÃO.\nEXPULSAR MUITOS ESPÍRITOS IMPUROS / UNGIR COM ÓLEO DOENTES / CURAR.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|16º Domingo|evangelho|Mc 6,30-34": "(ROTEIRO EDITORIAL — RETORNO DOS APÓSTOLOS, DESCANSO E COMPAIXÃO)\nAPÓSTOLOS VOLTAR ENCONTRAR JESUS / CONTAR TUDO QUE FIZERAM E ENSINARAM.\nJESUS: VENHAM COMIGO PARA LOCAL ISOLADO / DESCANSAR UM POUCO.\nMUITAS PESSOAS IR E VIR / DISCÍPULOS NEM TEMPO PARA COMER.\nJESUS E DISCÍPULOS PEGAR BARCO / IR LUGAR RETIRADO.\nPESSOAS VER PARA ONDE BARCO IR / DE VÁRIAS CIDADES / CORRER A PÉ / CHEGAR PRIMEIRO.\nJESUS DESCER BARCO / VER GRANDE MULTIDÃO.\nJESUS SENTIR COMPAIXÃO / PESSOAS COMO OVELHAS SEM PASTOR.\nJESUS COMEÇAR ENSINAR MUITAS COISAS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|22º Domingo|evangelho|Mc 7,1-8.14-15.21-23": "(ROTEIRO EDITORIAL — FARISEUS, ESCRIBAS, DISCÍPULOS, JESUS, MULTIDÃO; NÃO CONFUNDIR CRÍTICA À HIPOCRISIA COM CRÍTICA À HIGIENE)\n(CENA 1: COSTUMES RITUAIS)\nFARISEUS E ESCRIBAS VINDOS JERUSALÉM / REUNIR PERTO JESUS.\nVER ALGUNS DISCÍPULOS COMER SEM LAVAR MÃOS CONFORME RITO.\nNARRADOR EXPLICAR TRADIÇÃO DE LAVAR MÃOS / UTENSÍLIOS / AO VOLTAR MERCADO.\nFARISEUS: POR QUE SEUS DISCÍPULOS NÃO SEGUEM TRADIÇÃO DOS ANTIGOS?\n(CENA 2: JESUS CITA ISAÍAS)\nJESUS: ISAÍAS FALAR DE VOCÊS HIPÓCRITAS.\nPOVO HONRAR DEUS COM LÁBIOS / MAS CORAÇÃO LONGE DE DEUS.\nCULTO VAZIO / ENSINAR MANDAMENTOS HUMANOS COMO SE FOSSEM DE DEUS.\nVOCÊS DEIXAR MANDAMENTO DE DEUS / AGARRAR-SE A TRADIÇÕES HUMANAS.\n(CENA 3: O QUE TORNA IMPURO)\nJESUS CHAMAR MULTIDÃO: OUVIR E ENTENDER.\nNÃO COISAS QUE ENTRAM NO SER HUMANO QUE TORNAM CORAÇÃO IMPURO.\nMAL QUE SAI DO INTERIOR HUMANO / ISSO CONTAMINA.\nDO CORAÇÃO / MAUS PENSAMENTOS E INTENÇÕES:\nIMORALIDADE / ROUBO / ASSASSINATO / ADULTÉRIO / COBIÇA / INJUSTIÇA / MENTIRA / INVEJA / DIFAMAÇÃO / ORGULHO / INSENSATEZ.\nESSES MALES / VIR DO INTERIOR / TORNAR PESSOA IMPURA.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|23º Domingo|evangelho|Mc 7,31-37": "(ROTEIRO EDITORIAL — NARRADOR, JESUS, HOMEM SURDO COM DIFICULDADE DE FALA E MULTIDÃO. NÃO TRATAR DEFICIÊNCIA COMO CULPA.)\nJESUS SAIR REGIÃO TIRO / PASSAR SIDÔNIA / CHEGAR MAR GALILEIA PELO TERRITÓRIO DECÁPOLE.\nPESSOAS TRAZER HOMEM SURDO / ELE FALAR COM DIFICULDADE.\nPESSOAS PEDIR JESUS IMPOR MÃOS NO HOMEM.\nJESUS LEVAR HOMEM PARA LONGE MULTIDÃO / ATENDER EM PARTICULAR.\nJESUS COLOCAR DEDOS NOS OUVIDOS DELE / COM SALIVA TOCAR LÍNGUA.\nJESUS OLHAR CÉU / SUSPIRAR / DIZER:\nEFFATHÁ / SIGNIFICA ABRE-TE.\nHOMEM / IMEDIATAMENTE OUVIDOS ABRIR / SUA DIFICULDADE DE FALA DESAPARECER / FALAR CLARAMENTE.\nJESUS PEDIR PESSOAS NÃO DIVULGAR.\nMAS QUANTO MAIS ORIENTAR SILÊNCIO / MAIS PESSOAS ESPALHAR NOTÍCIA.\nMULTIDÃO MUITO ADMIRADA: JESUS FAZER TUDO BEM / FAZ PESSOAS SURDAS OUVIR E PESSOAS QUE NÃO FALAVAM CONSEGUIR FALAR.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|24º Domingo|evangelho|Mc 8,27-35": "(ROTEIRO EDITORIAL — CESAREIA DE FILIPE, PEDRO, JESUS E DISCÍPULOS)\nJESUS VIAJAR COM DISCÍPULOS EM DIREÇÃO POVOADOS CESAREIA FILIPE.\nJESUS PERGUNTAR NO CAMINHO: PESSOAS DIZER QUEM EU SOU?\nDISCÍPULOS: ALGUNS DIZER JOÃO BATISTA / OUTROS ELIAS / OUTROS PROFETA.\nJESUS: E VOCÊS / QUEM DIZEM QUE EU SOU?\nPEDRO: VOCÊ É MESSIAS.\nJESUS ORDENAR NÃO CONTAR A NINGUÉM.\n(CENA 2: PREDIÇÃO PAIXÃO)\nJESUS ENSINAR COM CLAREZA:\nFILHO DO HOMEM PRECISA SOFRER MUITO / REJEITADO POR ANCIÃOS / SUMOS SACERDOTES / ESCRIBAS.\nSER MORTO / RESSUSCITAR DEPOIS TRÊS DIAS.\nPEDRO CHAMAR JESUS À PARTE / CONTESTAR.\nJESUS VIRAR PARA DISCÍPULOS / REPREENDER PEDRO:\nAFASTA-TE SATANÁS / VOCÊ PENSAR SEGUNDO HOMENS / NÃO SEGUNDO DEUS.\n(CENA 3: CAMINHO DO DISCÍPULO)\nJESUS CHAMAR MULTIDÃO E DISCÍPULOS:\nQUEM QUERER SEGUIR-ME / RENUNCIAR A SI MESMO / CARREGAR SUA CRUZ / SEGUIR.\nQUEM QUISER SALVAR SUA VIDA / PERDER.\nQUEM PERDER VIDA POR MIM E EVANGELHO / SALVAR.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|25º Domingo|evangelho|Mc 9,30-37": "(ROTEIRO EDITORIAL — CONTRASTE ENTRE ANÚNCIO DA PAIXÃO E DISPUTA POR PRESTÍGIO)\nJESUS E DISCÍPULOS CAMINHAR GALILEIA / JESUS QUERER ENSINAR EM PARTICULAR.\nJESUS: FILHO DO HOMEM SER ENTREGUE ÀS MÃOS DOS HOMENS / ELES O MATARÃO.\nDEPOIS TRÊS DIAS / ELE RESSUSCITARÁ.\nDISCÍPULOS NÃO COMPREENDER / TER MEDO PERGUNTAR.\n(CENA: CAFARNAUM EM CASA)\nJESUS: O QUE VOCÊS DISCUTIRAM NO CAMINHO?\nDISCÍPULOS FICAR CALADOS / PORQUE DISCUTIRAM QUAL DELES SER MAIOR.\nJESUS SENTAR / CHAMAR DOZE:\nQUEM QUISER PRIMEIRO / SEJA ÚLTIMO DE TODOS / SERVO DE TODOS.\nJESUS PEGAR CRIANÇA / COLOCAR CENTRO / ABRAÇAR.\nJESUS: QUEM RECEBER CRIANÇA COMO ESSA EM MEU NOME / RECEBER A MIM.\nQUEM RECEBER A MIM / RECEBER TAMBÉM DEUS QUE ME ENVIOU.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|26º Domingo|evangelho|Mc 9,38-43.45.47-48": "(ROTEIRO EDITORIAL — EVITAR ENCENAR MUTILAÇÃO LITERAL; JESUS UTILIZA IMAGENS EXTREMAS PARA REJEITAR O PECADO)\nJOÃO DISCÍPULO → JESUS: MESTRE / NÓS VER HOMEM EXPULSAR DEMÔNIOS EM SEU NOME.\nNÓS TENTAR PROIBIR / PORQUE ELE NÃO CAMINHAR COM NOSSO GRUPO.\nJESUS: NÃO PROIBIR / QUEM FAZER MILAGRE EM MEU NOME / NÃO FALAR MAL DE MIM LOGO DEPOIS.\nQUEM NÃO ESTAR CONTRA NÓS / ESTAR POR NÓS.\nQUEM DER COPO ÁGUA A VOCÊS POR PERTENCEREM A CRISTO / RECEBER RECOMPENSA.\n(CENA 2: GRAVIDADE DE FAZER OUTRO CAIR)\nSE ALGUÉM LEVAR UM DOS PEQUENOS QUE CREEM EM MIM A PECAR / GRAVÍSSIMO.\nJESUS USAR IMAGEM DE PEDRA DE MOINHO NO PESCOÇO / LANÇADO MAR / PARA MOSTRAR GRAVIDADE.\n(CENA 3: AFASTAR OCASIÕES DE PECADO — FIGURA, NÃO ORDEM DE AGRESSÃO)\nSE MÃO LEVAR AO PECADO / JESUS DIZER CORTAR COMO IMAGEM DE ROMPER COM MAL.\nMELHOR RENUNCIAR A ISSO / ENTRAR VIDA / QUE PERSISTIR NO MAL E IR PARA GEENA.\nSE PÉ LEVAR PECADO / MESMA IMAGEM.\nSE OLHO LEVAR PECADO / IMAGEM DE AFASTÁ-LO / NÃO PRATICAR MAL.\nGEENA / IMAGEM DO JUÍZO / FOGO NÃO APAGAR / VERME NÃO MORRER.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|27º Domingo|evangelho|Mc 10,2-16": "(ROTEIRO EDITORIAL — PRIMEIRO DIÁLOGO SOBRE MATRIMÔNIO; DEPOIS ACOLHIDA DE CRIANÇAS. NÃO CRIAR FORMA BREVE INEXISTENTE NO ARQUIVO.)\nFARISEUS APROXIMAR JESUS / QUERER TESTAR.\nPERGUNTAR: HOMEM PODE REPUDIAR SUA ESPOSA?\nJESUS: MOISÉS ORDENAR O QUÊ?\nFARISEUS: MOISÉS PERMITIR DOCUMENTO DIVÓRCIO.\nJESUS: ELE PERMITIR POR CAUSA CORAÇÃO DE VOCÊS ENDURECIDO.\nDESDE CRIAÇÃO / DEUS CRIAR HOMEM E MULHER.\nHOMEM DEIXAR PAI E MÃE / UNIR À ESPOSA.\nDOIS TORNAR-SE UMA SÓ CARNE / NÃO MAIS DOIS.\nO QUE DEUS UNIR / HUMANO NÃO DEVE SEPARAR.\n(CENA: DISCÍPULOS EM CASA)\nDISCÍPULOS PERGUNTAR NOVAMENTE.\nJESUS EXPLICAR CONSEQUÊNCIA DE REPÚDIO E NOVA UNIÃO / ADULTÉRIO DO HOMEM OU DA MULHER.\n(CENA: CRIANÇAS)\nPESSOAS TRAZER CRIANÇAS PARA JESUS TOCAR E ABENÇOAR.\nDISCÍPULOS TENTAR IMPEDIR.\nJESUS FICAR INDIGNADO:\nDEIXAR CRIANÇAS VIR A MIM / NÃO IMPEÇAM.\nREINO DE DEUS PERTENCER A QUEM ACOLHER COMO CRIANÇA.\nQUEM NÃO ACOLHER REINO COMO CRIANÇA / NÃO ENTRAR.\nJESUS ABRAÇAR CRIANÇAS / IMPOR MÃOS / ABENÇOAR.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|28º Domingo|evangelho|Mc 10,17-30": "(ROTEIRO EDITORIAL — HOMEM RICO, JESUS, DISCÍPULOS E PEDRO; IMAGEM DO CAMELO É FIGURADA)\nJESUS COMEÇAR CAMINHO / HOMEM CORRER / AJOELHAR DIANTE JESUS:\nBOM MESTRE / O QUE FAZER PARA ALCANÇAR VIDA ETERNA?\nJESUS: POR QUE CHAMAR BOM? SÓ DEUS É BOM.\nVOCÊ CONHECER MANDAMENTOS:\nNÃO MATAR / NÃO COMETER ADULTÉRIO / NÃO ROUBAR / NÃO TESTEMUNHAR FALSO / NÃO DEFRAUDAR / HONRAR PAI E MÃE.\nHOMEM: MESTRE / EU CUMPRIR DESDE JUVENTUDE.\nJESUS OLHAR COM AFETO:\nFALTA UMA COISA / VENDER BENS / DAR DINHEIRO A POBRES.\nVOCÊ TER TESOURO NO CÉU / DEPOIS VIR SEGUIR-ME.\nHOMEM FICAR TRISTE / IR EMBORA / POSSUIR MUITAS RIQUEZAS.\n(CENA: DISCÍPULOS)\nJESUS: COMO É DIFÍCIL PARA QUEM CONFIA NAS RIQUEZAS ENTRAR REINO DE DEUS.\nDISCÍPULOS ADMIRAR.\nJESUS: MAIS FÁCIL CAMELO PASSAR PELO FUNDO AGULHA DO QUE RICO ENTRAR REINO.\nDISCÍPULOS: ENTÃO QUEM PODE SER SALVO?\nJESUS: AOS HUMANOS / IMPOSSÍVEL / MAS DEUS PODE TUDO.\n(CENA: PEDRO)\nPEDRO: NÓS DEIXAR TUDO PARA SEGUIR VOCÊ.\nJESUS: QUEM DEIXAR CASA, FAMÍLIA, TERRAS POR MIM E PELO EVANGELHO / RECEBERÁ CEM VEZES MAIS JÁ NESTA VIDA / JUNTO PERSEGUIÇÕES.\nNO MUNDO FUTURO / VIDA ETERNA.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|29º Domingo|evangelho|Mc 10,35-45": "(ROTEIRO EDITORIAL — TIAGO E JOÃO, JESUS E OS OUTROS DEZ)\nTIAGO E JOÃO / FILHOS ZEBEDEU / APROXIMAR JESUS:\nMESTRE / QUEREMOS QUE FAÇA O QUE PEDIRMOS.\nJESUS: O QUE VOCÊS QUEREM?\nIRMÃOS: QUANDO VOCÊ ESTIVER NA GLÓRIA / UM DE NÓS À SUA DIREITA / OUTRO À ESQUERDA.\nJESUS: VOCÊS NÃO SABEM O QUE PEDEM.\nVOCÊS PODEM BEBER CÁLICE QUE EU BEBEREI? / RECEBER BATISMO QUE EU RECEBEREI?\nELES: PODEMOS.\nJESUS: VOCÊS PARTICIPARÃO DESSE SOFRIMENTO.\nMAS LUGAR DIREITA E ESQUERDA / NÃO CABE A MIM CONCEDER / RESERVADO A QUEM DEUS PREPAROU.\nOUTROS DEZ DISCÍPULOS OUVIR / FICAR INDIGNADOS COM TIAGO E JOÃO.\nJESUS CHAMAR TODOS:\nGOVERNANTES DO MUNDO DOMINAR POVOS / PODEROSOS IMPOR SUA AUTORIDADE.\nMAS ENTRE VOCÊS NÃO DEVE SER ASSIM.\nQUEM QUER GRANDE / SER SERVO DOS OUTROS.\nQUEM QUER PRIMEIRO / SER ESCRAVO DE TODOS.\nFILHO DO HOMEM NÃO VEIO PARA SER SERVIDO.\nELE VEIO PARA SERVIR E DAR SUA VIDA COMO RESGATE DE MUITOS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|30º Domingo|evangelho|Mc 10,46-52": "(ROTEIRO EDITORIAL — BARTIMEU, MULTIDÃO E JESUS. NÃO TRATAR DEFICIÊNCIA COMO FALTA DE DIGNIDADE)\nJESUS COM DISCÍPULOS E MULTIDÃO / SAIR CIDADE JERICÓ.\nBARTIMEU / FILHO DE TIMEU / CEGO / SENTADO À BEIRA DO CAMINHO PEDIR ESMOLA.\nELE OUVIR JESUS DE NAZARÉ PASSAR / GRITAR:\nJESUS / FILHO DE DAVID / TER PIEDADE DE MIM!\nMUITAS PESSOAS REPREENDER / MANDAR CALAR.\nBARTIMEU GRITAR MAIS FORTE: FILHO DE DAVID / TER PIEDADE DE MIM!\nJESUS PARAR / DIZER: CHAMAR ELE.\nPESSOAS: CORAGEM / LEVANTAR / JESUS CHAMAR VOCÊ.\nBARTIMEU JOGAR CAPA DE LADO / LEVANTAR DEPRESSA / IR JESUS.\nJESUS: O QUE VOCÊ QUER QUE EU FAÇA?\nBARTIMEU: MESTRE / EU QUERO ENXERGAR.\nJESUS: VÁ / SUA FÉ TE SALVOU.\nBARTIMEU RECUPERAR VISTA IMEDIATAMENTE / SEGUIR JESUS PELO CAMINHO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|31º Domingo|evangelho|Mc 12,28-34": "(ROTEIRO EDITORIAL — ESCRIBA PERGUNTA, JESUS RESPONDE; DISTINGUIR DOIS MANDAMENTOS)\nESCRIBA APROXIMAR JESUS / PERGUNTAR:\nQUAL É O PRIMEIRO DE TODOS MANDAMENTOS?\nJESUS: PRIMEIRO / ESCUTA ISRAEL.\nSENHOR NOSSO DEUS / ÚNICO SENHOR.\nAMAR SENHOR DEUS COM TODO CORAÇÃO / TODA ALMA / TODO ENTENDIMENTO / TODAS FORÇAS.\nSEGUNDO MANDAMENTO / AMAR PRÓXIMO COMO A SI MESMO.\nNÃO EXISTIR MANDAMENTO MAIOR QUE ESSES.\nESCRIBA: MESTRE / VOCÊ ESTÁ CERTO.\nDEUS É ÚNICO / NÃO HÁ OUTRO ALÉM DELE.\nAMAR DEUS COM CORAÇÃO / INTELIGÊNCIA / FORÇAS / AMAR PRÓXIMO COMO SI.\nISSO VALER MAIS QUE OFERENDAS E SACRIFÍCIOS.\nJESUS RECONHECER RESPOSTA SÁBIA:\nVOCÊ NÃO ESTÁ LONGE REINO DE DEUS.\nDEPOIS / NINGUÉM MAIS OUSAR INTERROGAR JESUS.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|32º Domingo|evangelho|Mc 12,38-44": "(ROTEIRO EDITORIAL — ENSINAMENTO SOBRE ESCRIBAS E OFERTA DA VIÚVA. EVITAR ROMANTIZAR EXPLORAÇÃO DE PESSOAS POBRES.)\n(CENA 1: JESUS ADVERTE)\nJESUS ENSINAR MULTIDÃO:\nCUIDADO COM ESCRIBAS QUE GOSTAR ROUPAS LONGAS / SAUDAÇÕES NAS PRAÇAS.\nELES GOSTAR MELHORES ASSENTOS NAS SINAGOGAS / MELHORES LUGARES NAS FESTAS.\nELES EXPLORAR CASAS DE VIÚVAS / FINGIR ORAR MUITO.\nJULGAMENTO DELES / MAIS SEVERO.\n(CENA 2: OFERTAS NO TEMPLO)\nJESUS SENTAR DIANTE CAIXA DE OFERTAS / OBSERVAR.\nPESSOAS RICAS COLOCAR MUITO DINHEIRO.\nVIÚVA POBRE CHEGAR / DEPOSITAR DUAS MOEDAS PEQUENAS.\nJESUS CHAMAR DISCÍPULOS:\nESSA VIÚVA POBRE / DEPOSITAR MAIS QUE TODOS.\nOUTROS DAR DO DINHEIRO SOBRANDO.\nELA / MESMO NA POBREZA / DAR TUDO QUE POSSUIR PARA VIVER.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|33º Domingo|evangelho|Mc 13,24-32": "(ROTEIRO EDITORIAL — LINGUAGEM PROFÉTICA E APOCALÍPTICA; NÃO TRANSFORMAR IMAGENS EM PREVISÃO DATADA)\nJESUS FALAR DISCÍPULOS:\nDEPOIS TEMPO GRANDE AFLIÇÃO / SOL ESCURECER / LUA NÃO ILUMINAR.\nESTRELAS CAIR CÉU / FORÇAS DOS CÉUS ABALADAS.\nENTÃO PESSOAS VER FILHO DO HOMEM VIR ENTRE NUVENS / GRANDE PODER E GLÓRIA.\nELE ENVIAR ANJOS / REUNIR ELEITOS DOS QUATRO CANTOS DO MUNDO / DA TERRA AO CÉU.\n(CENA 2: FIGUEIRA)\nJESUS: APRENDER FIGUEIRA.\nQUANDO RAMOS FICAR TENROS / FOLHAS CRESCER / VOCÊS SABER VERÃO PRÓXIMO.\nASSIM QUANDO VIREM SINAIS / SABER FILHO DO HOMEM ESTÁ PRÓXIMO / À PORTA.\nEU DIGO / ESTA GERAÇÃO NÃO PASSARÁ SEM QUE ISSO ACONTEÇA.\nCÉU E TERRA PODEM PASSAR / MINHAS PALAVRAS NÃO PASSARÃO.\nDIA E HORA / NINGUÉM SABER / NEM ANJOS / NEM FILHO / SOMENTE PAI.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|TEMPO COMUM — ANO B|34º Domingo — Cristo Rei|evangelho|Jo 18,33-37": "(ROTEIRO EDITORIAL — DIÁLOGO PILATOS E JESUS; NÃO IDENTIFICAR REINO DE CRISTO COM PODER POLÍTICO TERRENO)\nPILATOS → JESUS: VOCÊ É REI DOS JUDEUS?\nJESUS → PILATOS: VOCÊ PERGUNTAR POR SI MESMO / OU OUTROS FALARAM ISSO SOBRE MIM?\nPILATOS: EU SOU JUDEU? / SEU POVO E CHEFES SACERDOTES ENTREGARAM VOCÊ A MIM.\nO QUE VOCÊ FEZ?\nJESUS: MEU REINO NÃO É DESTE MUNDO.\nSE MEU REINO FOSSE DESTE MUNDO / MEUS GUARDAS LUTARIAM PARA EU NÃO SER ENTREGUE.\nMAS MEU REINO NÃO TER ORIGEM AQUI.\nPILATOS: ENTÃO VOCÊ É REI?\nJESUS: É COMO VOCÊ DIZ / EU SOU REI.\nEU NASCI E VIM MUNDO PARA DAR TESTEMUNHO VERDADE.\nQUEM PERTENCER À VERDADE / ESCUTAR MINHA VOZ.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|QUARESMA|1º Domingo|primeira-leitura|Gn 9,8-15": "(ROTEIRO EDITORIAL — DEUS FALA A NOÉ, FILHOS E TODOS SERES VIVOS)\nDEUS → NOÉ E FILHOS:\nEU ESTABELECER ALIANÇA COM VOCÊS / COM DESCENDENTES / COM TODOS SERES VIVOS.\nAVES / ANIMAIS DOMÉSTICOS / ANIMAIS SELVAGENS / TODOS QUE SAÍRAM ARCA.\nEU PROMETER / NENHUMA CRIATURA NOVAMENTE SERÁ DESTRUÍDA POR ÁGUAS DILÚVIO.\nNUNCA MAIS DILÚVIO DEVASTARÁ TODA TERRA.\n(CENA 2: SINAL DA ALIANÇA)\nDEUS: SINAL ALIANÇA ENTRE MIM E VOCÊS / TODOS ANIMAIS / FUTURAS GERAÇÕES.\nEU COLOCAREI MEU ARCO NAS NUVENS / SINAL ALIANÇA COM TERRA.\nQUANDO NUVENS COBRIR TERRA / ARCO APARECER / EU LEMBRAR ALIANÇA.\nÁGUAS NÃO MAIS FORMARÃO DILÚVIO PARA DESTRUIR TODOS SERES.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|1º Domingo|segunda-leitura|1Pd 3,18-22": "(ROTEIRO EDITORIAL — CRISTO JUSTO, NOÉ, BATISMO E RESSURREIÇÃO)\nPEDRO → COMUNIDADE:\nCRISTO / UMA VEZ POR TODAS / MORRER PELOS PECADOS.\nELE JUSTO / POR PESSOAS INJUSTAS / PARA CONDUZIR VOCÊS A DEUS.\nMORRER NA CARNE / RECEBER VIDA PELO ESPÍRITO.\nPOR ESSE ESPÍRITO / CRISTO ANUNCIAR A ESPÍRITOS NA PRISÃO DA MORTE.\nELES HAVIAM DESOBEDECIDO NOS TEMPOS DE NOÉ.\nDEUS ESPERAR PACIENTEMENTE / NOÉ CONSTRUIR ARCA.\nSOMENTE OITO PESSOAS / PASSAR PELAS ÁGUAS / SER SALVAS.\n(CENA 2: SENTIDO DO BATISMO)\nÁGUA DA ARCA / FIGURA DO BATISMO.\nBATISMO AGORA SALVAR VOCÊS.\nNÃO APENAS LAVAR SUJEIRA DO CORPO / MAS COMPROMISSO DE BOA CONSCIÊNCIA DIANTE DE DEUS.\nISSO ACONTECER PELA RESSURREIÇÃO DE JESUS CRISTO.\nJESUS SUBIR AO CÉU / ESTAR À DIREITA DE DEUS.\nANJOS E PODERES / SOB SUA AUTORIDADE.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|1º Domingo|evangelho|Mc 1,12-15": "(ROTEIRO EDITORIAL — DESERTO E GALILEIA; EVANGELHO COMEÇA APÓS ACLAMAÇÃO NO TEXTO IMPORTADO)\nESPÍRITO SANTO CONDUZIR JESUS PARA DESERTO.\nJESUS PERMANECER QUARENTA DIAS / SATANÁS TENTAR JESUS.\nJESUS ENTRE ANIMAIS SELVAGENS / ANJOS SERVIR JESUS.\n(CENA 2: DEPOIS DA PRISÃO DE JOÃO)\nJOÃO BATISTA SER PRESO / JESUS IR GALILEIA.\nJESUS PROCLAMAR EVANGELHO DE DEUS:\nTEMPO JÁ CUMPRIR.\nREINO DE DEUS APROXIMAR.\nVOCÊS ARREPENDER-SE / ACREDITAR NO EVANGELHO.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|QUARESMA|2º Domingo|primeira-leitura|Gn 22,1-2.9-13.15-18": "(ROTEIRO EDITORIAL — ABRAÃO, ISAAC, ANJO; EVITAR INTERPRETAR PROVA COMO MANDATO ATUAL DE VIOLÊNCIA)\nDEUS COLOCAR ABRAÃO À PROVA / CHAMAR: ABRAÃO!\nABRAÃO: AQUI ESTOU.\nDEUS: PEGAR ISAAC / SEU FILHO ÚNICO TÃO AMADO / IR TERRA MORIÁ.\nALI / NO MONTE QUE EU INDICAR / OFERECER EM SACRIFÍCIO.\n(CENA 2: ALTAR NO MONTE)\nABRAÃO E ISAAC CHEGAR LOCAL / ABRAÃO CONSTRUIR ALTAR / PREPARAR LENHA.\nABRAÃO LEVANTAR MÃO COM FACA.\nANJO SENHOR GRITAR DO CÉU: ABRAÃO / ABRAÃO!\nABRAÃO: AQUI ESTOU.\nANJO: NÃO LEVANTAR MÃO CONTRA MENINO / NÃO FAZER MAL ALGUM.\nAGORA SEI QUE VOCÊ RESPEITA DEUS / NÃO RECUSAR SEU FILHO ÚNICO.\nABRAÃO LEVANTAR OLHOS / VER CARNEIRO CHIFRES PRESOS NUM ARBUSTO.\nABRAÃO OFERECER CARNEIRO / EM VEZ DE FILHO.\n(CENA 3: PROMESSA)\nANJO CHAMAR SEGUNDA VEZ / DIZER PALAVRA DE DEUS.\nDEUS JURAR / POR CAUSA DA OBEDIÊNCIA DE ABRAÃO:\nEU TE ABENÇOAR / MULTIPLICAR SUA DESCENDÊNCIA COMO ESTRELAS CÉU / AREIA MAR.\nDESCENDÊNCIA VENCER INIMIGOS.\nPOR SUA DESCENDÊNCIA / TODAS NAÇÕES TERRA SERÃO ABENÇOADAS.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|2º Domingo|segunda-leitura|Rm 8,31-34": "(ROTEIRO EDITORIAL — PAULO ARGUMENTA POR MEIO DE PERGUNTAS)\nPAULO → IRMÃOS:\nSE DEUS ESTAR AO NOSSO LADO / QUEM PODER CONTRA NÓS?\nDEUS NÃO POUPAR PRÓPRIO FILHO / ENTREGAR POR TODOS NÓS.\nCOM SEU FILHO / COMO NÃO NOS DAR TAMBÉM TODAS COISAS?\nQUEM ACUSARÁ PESSOAS ESCOLHIDAS POR DEUS?\nDEUS MESMO JUSTIFICAR.\nQUEM CONDENARÁ?\nCRISTO JESUS MORRER / MAIS AINDA / RESSUSCITAR.\nCRISTO ESTAR À DIREITA DE DEUS / INTERCEDER POR NÓS.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|2º Domingo|evangelho|Mc 9,2-10": "(ROTEIRO EDITORIAL — TRANSFIGURAÇÃO; DEUS PAI, JESUS, PEDRO, TIAGO, JOÃO, MOISÉS E ELIAS)\nJESUS LEVAR PEDRO / TIAGO / JOÃO / SUBIR MONTE ALTO AFASTADO.\nDIANTE DELES / JESUS TRANSFIGURAR-SE / APARÊNCIA MUDAR.\nROUPAS DE JESUS BRILHAR / BRANCO MUITO INTENSO.\nMOISÉS E ELIAS APARECER / CONVERSAR COM JESUS.\nPEDRO → JESUS: MESTRE / BOM ESTAR AQUI.\nVAMOS FAZER TRÊS TENDAS / UMA PARA VOCÊ / OUTRA MOISÉS / OUTRA ELIAS.\nPEDRO ESTAR COM MEDO / NEM SABER O QUE DIZER.\nNUVEM COBRIR TODOS / VOZ DA NUVEM:\nESTE É MEU FILHO AMADO / ESCUTEM ELE.\nDE REPENTE / DISCÍPULOS OLHAR / SÓ JESUS FICAR COM ELES.\n(CENA: DESCIDA DO MONTE)\nJESUS ORDENAR NÃO CONTAR O QUE VIRAM A NINGUÉM / ATÉ FILHO DO HOMEM RESSUSCITAR DOS MORTOS.\nDISCÍPULOS GUARDAR SILÊNCIO / DISCUTIR ENTRE SI O QUE SIGNIFICAR RESSUSCITAR.\n(ENCERRAMENTO: PALAVRA DA SALVAÇÃO.)",
  "B|QUARESMA|3º Domingo|primeira-leitura|Ex 20,1-17": "(ROTEIRO EDITORIAL — ATENÇÃO: A FONTE DISPONÍVEL É EXPLICITAMENTE A FORMA BREVE EX 20,1-3.7-8.12-17, NÃO O TEXTO INTEGRAL 1-17.)\nDEUS FALAR A SEU POVO:\nEU SENHOR SEU DEUS / TIREI VOCÊS DO EGITO / LUGAR ESCRAVIDÃO.\nNÃO TER OUTROS DEUSES DIANTE DE MIM.\nNÃO USAR NOME SENHOR DEUS EM VÃO.\nLEMBRAR DIA SÁBADO / SANTIFICAR.\nHONRAR PAI E MÃE / PARA VIDA LONGA NA TERRA QUE DEUS DAR.\nNÃO MATAR.\nNÃO COMETER ADULTÉRIO.\nNÃO ROUBAR.\nNÃO DAR TESTEMUNHO FALSO CONTRA PRÓXIMO.\nNÃO COBIÇAR CASA PESSOA / NÃO DESEJAR ESPOSA / SERVO / SERVA / BOI / JUMENTO / QUALQUER COISA QUE PERTENCER A OUTRA PESSOA.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)\n(NOTA: REFERÊNCIA NO ÍNDICE É ABRANGENTE, MAS O TEXTO IMPORTADO CONTÉM APENAS VERSÍCULOS SELECIONADOS.)",
  "B|QUARESMA|3º Domingo|segunda-leitura|1Cor 1,22-25": "(ROTEIRO EDITORIAL — CONTRASTE ENTRE EXPECTATIVAS HUMANAS E CRISTO CRUCIFICADO)\nPAULO → IRMÃOS:\nPOVO JUDEU EXIGIR SINAIS MILAGROSOS / GREGOS BUSCAR SABEDORIA.\nMAS NÓS ANUNCIAR CRISTO CRUCIFICADO.\nPARA UNS / ISSO MOTIVO ESCÂNDALO.\nPARA OUTROS / PARECER LOUCURA.\nMAS PARA PESSOAS QUE DEUS CHAMAR / TANTO JUDEUS COMO GREGOS:\nCRISTO É PODER DE DEUS / SABEDORIA DE DEUS.\nAQUILO QUE PARECER LOUCURA EM DEUS / MAIS SÁBIO QUE SABEDORIA HUMANA.\nAQUILO QUE PARECER FRAQUEZA DE DEUS / MAIS FORTE QUE FORÇA HUMANA.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|4º Domingo|primeira-leitura|2Cr 36,14-17.19-23": "(ROTEIRO EDITORIAL — CAUSA HISTÓRICA, EXÍLIO E RETORNO; TEXTO NÃO SUBSTITUI LEITURA INTEGRAL)\nCHEFES SACERDOTES E POVO / MULTIPLICAR INFIDELIDADES.\nIMITAR COSTUMES RELIGIOSOS DE OUTROS POVOS / PROFANAR TEMPLO DEUS EM JERUSALÉM.\nDEUS DOS ANTEPASSADOS / REPETIDAMENTE ENVIAR MENSAGEIROS.\nDEUS DESEJAR POUPAR POVO E TEMPLO.\nMAS PESSOAS ZOMBAR MENSAGEIROS / DESPREZAR PALAVRA DE DEUS / RIDICULARIZAR PROFETAS.\nATÉ NÃO HAVER MAIS REMÉDIO / CONSEQUÊNCIA JUÍZO DIVINO.\n(CENA: QUEDA JERUSALÉM)\nCALDEUS / INCENDIAR TEMPLO / DESTRUIR MUROS JERUSALÉM / PALÁCIOS E OBJETOS PRECIOSOS.\nREI CALDEUS LEVAR SOBREVIVENTES CATIVOS PARA BABILÔNIA.\nPOVO SERVIR A OUTROS ATÉ CHEGAR DOMÍNIO PERSAS.\nISSO CUMPRIR PALAVRA PROFETA JEREMIAS.\nTERRA DESCANSAR DURANTE DESOLAÇÃO / SETENTA ANOS.\n(CENA: CIRO REI PÉRSIA)\nPRIMEIRO ANO REINADO CIRO / DEUS MOVER CORAÇÃO DO REI.\nCIRO ANUNCIAR EM TODO REINO POR ESCRITO E VOZ:\nSENHOR DEUS DO CÉU / DAR-ME REINOS DA TERRA.\nDEUS CONFIAR A MIM CONSTRUÇÃO DE TEMPLO EM JERUSALÉM JUDA.\nQUEM PERTENCER POVO DE DEUS / PODE IR / DEUS ACOMPANHAR.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|4º Domingo|segunda-leitura|Ef 2,4-10": "(ROTEIRO EDITORIAL — GRAÇA, FÉ E OBRAS; NÃO INVERTER CAUSA DA SALVAÇÃO)\nPAULO → IRMÃOS:\nDEUS MUITO RICO EM MISERICÓRDIA / AMAR NÓS PROFUNDAMENTE.\nMESMO NÓS MORTOS ESPIRITUALMENTE POR PECADOS / DEUS DAR VIDA JUNTO COM CRISTO.\nVOCÊS SER SALVOS PELA GRAÇA.\nCOM CRISTO / DEUS NOS RESSUSCITAR / FAZER PARTICIPAR DA VIDA CELESTE.\nDEUS QUERER MOSTRAR FUTURAS GERAÇÕES / RIQUEZA DA SUA GRAÇA E BONDADE EM JESUS CRISTO.\nSALVAÇÃO / POR GRAÇA / MEDIANTE FÉ.\nISSO NÃO VIR DA FORÇA HUMANA / É PRESENTE DE DEUS.\nNÃO POR MÉRITO OBRAS / NINGUÉM PODER SE GLORIAR.\nNÓS OBRA DE DEUS / CRIADOS EM CRISTO JESUS / PARA PRATICAR BOAS OBRAS.\nDEUS JÁ PREPARAR CAMINHO DE BOAS AÇÕES / NÓS DEVEMOS SEGUIR.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|5º Domingo|primeira-leitura|Jr 31,31-34": "(ROTEIRO EDITORIAL — DEUS PROMETE NOVA ALIANÇA)\nDEUS FALAR POR JEREMIAS:\nDIAS VIRÃO / EU ESTABELECER NOVA ALIANÇA COM CASA ISRAEL E CASA JUDÁ.\nALIANÇA DIFERENTE DA ANTIGA.\nEU PEGAR MÃO ANTEPASSADOS / TIRAR DO EGITO.\nELES VIOLAR ESSA ALIANÇA / MESMO EU SER SENHOR DELES.\n(CENA: NOVA ALIANÇA NO CORAÇÃO)\nEU COLOCAR MINHA LEI NO INTERIOR DELES / ESCREVER NO CORAÇÃO.\nEU SER DEUS DELES / ELES SERÃO MEU POVO.\nNÃO MAIS PRECISAR DIZER UNS AOS OUTROS 'CONHEÇAM SENHOR' COMO ANTES.\nTODOS / DESDE MENOR ATÉ MAIOR / ME CONHECERÃO.\nEU PERDOAR PECADOS DELES / NUNCA MAIS RECORDAR CULPAS.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|5º Domingo|segunda-leitura|Hb 5,7-9": "(ROTEIRO EDITORIAL — SOFRIMENTO, ORAÇÃO E OBEDIÊNCIA DE CRISTO)\nDURANTE VIDA MORTAL NA TERRA / JESUS ORAR A DEUS PAI.\nPEDIR COM CLAMORES E LÁGRIMAS / AO PAI QUE PODERIA LIVRAR DA MORTE.\nDEUS OUVIR SUA ORAÇÃO / POR CAUSA SUA REVERÊNCIA E OBEDIÊNCIA.\nJESUS SER FILHO / MESMO ASSIM / NO SOFRIMENTO APRENDER OBEDECER.\nJESUS COMPLETAR SUA MISSÃO.\nPARA TODOS QUE OBEDECEM A ELE / JESUS TORNAR FONTE DE SALVAÇÃO ETERNA.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|Domingo de Ramos e da Paixão|primeira-leitura|Is 50,4-7": "(ROTEIRO EDITORIAL — SERVO DO SENHOR FALA EM PRIMEIRA PESSOA)\nSENHOR DEUS / DAR-ME CAPACIDADE FALAR COMO DISCÍPULO.\nASSIM POSSO DAR PALAVRA DE ENCORAJAMENTO A PESSOAS CANSADAS E TRISTES.\nCADA MANHÃ / SENHOR ABRIR MEUS OUVIDOS PARA OUVIR COMO DISCÍPULO.\nDEUS ABRIR MEUS OUVIDOS / EU NÃO RESISTIR / NÃO RECUAR.\nA QUEM ME BATER / EU OFERECER COSTAS.\nA QUEM ARRANCAR BARBA / EU APRESENTAR FACE.\nPESSOAS INSULTAR / CUSPIR / EU NÃO ESCONDER ROSTO.\nSENHOR DEUS ME AJUDAR / POR ISSO NÃO FICAR ENVERGONHADO.\nMEU ROSTO FIRME COMO PEDRA / EU CONFIAR NÃO SER DECEPCIONADO.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)",
  "B|QUARESMA|Domingo de Ramos e da Paixão|segunda-leitura|Fl 2,6-11": "(ROTEIRO EDITORIAL — CRISTO HUMILHA-SE E DEUS O EXALTA)\nJESUS CRISTO / TER CONDIÇÃO DIVINA.\nNÃO USAR IGUALDADE COM DEUS PARA SEU PRÓPRIO PRIVILÉGIO.\nELE ESVAZIAR-SE / ASSUMIR CONDIÇÃO DE SERVO.\nTORNAR-SE SEMELHANTE SERES HUMANOS.\nCOMO HUMANO / HUMILHAR-SE / OBEDECER ATÉ MORTE / MORTE NA CRUZ.\nPOR ISSO DEUS O EXALTAR / DAR NOME ACIMA DE TODOS NOMES.\nDIANTE NOME JESUS / TODOS AJOELHAR / CÉU / TERRA / REGIÕES ABAIXO TERRA.\nTODAS LÍNGUAS PROCLAMAR: JESUS CRISTO É SENHOR.\nISSO PARA GLÓRIA DE DEUS PAI.\n(ENCERRAMENTO: PALAVRA DO SENHOR.)"
};
